mkdir -p src/lang tests scripts && cat > package.json <<'EOF'
{
  "name": "logomocja",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "build": "bun run scripts/build.ts",
    "test": "bun test tests",
    "dev": "bun run scripts/build.ts && bun run scripts/serve.ts"
  }
}
EOF
cat > tests/interpreter.test.ts <<'EOF'
import { test, expect } from "bun:test";
import { run } from "../src/lang";

const close = (a: number[], b: number[]) => a.every((v, i) => Math.abs(v - b[i]) < 1e-9);

test("kwadrat draws four segments forming a square", () => {
  const r = run(`kolor "#16866A"\ngrubosc 3\npowtorz 4 [\n np 120\n pw 90\n]`, "2d");
  expect(r.error).toBeNull();
  expect(r.segments.length).toBe(4);
  expect(r.segments[0]).toEqual({ from: [0, 0, 0], to: [0, 120, 0], color: "#16866a", width: 3 });
  expect(close(r.segments[1].to, [120, 120, 0])).toBe(true);
  expect(close(r.segments[3].to, [0, 0, 0])).toBe(true);
});
EOF
bun test tests 2>&1 | tail -5

