import { LogoError, LIMITS, type Pos } from "./errors";

export type TokenType =
  | "word" | "param" | "number" | "color" | "lbrack" | "rbrack"
  | "lparen" | "rparen" | "comma" | "op" | "cmp";

export interface Token extends Pos {
  type: TokenType;
  /** Raw text as written. */
  text: string;
  /** Lowercased name for words/params (without the leading colon). */
  name: string;
  value: number;
  spaceBefore: boolean;
  spaceAfter: boolean;
  /** First token on its line. */
  lineStart: boolean;
  /** Last token on its line. */
  lineEnd: boolean;
  index: number;
}

const isLetter = (c: string) => /[\p{L}_]/u.test(c);
const isWordChar = (c: string) => /[\p{L}\p{N}_]/u.test(c);
const isDigit = (c: string) => c >= "0" && c <= "9";

export function tokenize(src: string): Token[] {
  if (src.length > LIMITS.sourceChars) {
    const before = src.slice(0, LIMITS.sourceChars);
    const lines = before.split("\n");
    throw new LogoError(
      `Program jest za długi: najwyżej ${LIMITS.sourceChars.toLocaleString("pl-PL")} znaków.`,
      { line: lines.length, column: lines[lines.length - 1].length + 1 },
    );
  }
  const tokens: Token[] = [];
  let i = 0, line = 1, col = 1;
  let lastLine = 0;
  const n = src.length;
  const isSpace = (c: string | undefined) => c === undefined || /\s/.test(c) || c === ";";

  const push = (type: TokenType, text: string, start: number, pos: Pos, extra: Partial<Token> = {}) => {
    if (tokens.length >= LIMITS.tokens) {
      throw new LogoError(`Za dużo elementów programu: najwyżej ${LIMITS.tokens.toLocaleString("pl-PL")}.`, pos);
    }
    const prev = tokens[tokens.length - 1];
    const lineStart = pos.line !== lastLine;
    if (prev && lineStart) prev.lineEnd = true;
    lastLine = pos.line;
    tokens.push({
      type, text, name: "", value: 0,
      spaceBefore: start === 0 || isSpace(src[start - 1]),
      spaceAfter: isSpace(src[start + text.length]),
      lineStart, lineEnd: false, index: tokens.length,
      ...pos, ...extra,
    });
  };

  while (i < n) {
    const c = src[i];
    if (c === "\n") { i++; line++; col = 1; continue; }
    if (/\s/.test(c)) { i++; col++; continue; }
    if (c === ";") {
      while (i < n && src[i] !== "\n") { i++; col++; }
      continue;
    }
    const pos = { line, column: col };
    const start = i;
    const take = (len: number) => { const t = src.slice(i, i + len); i += len; col += len; return t; };

    if (isDigit(c) || (c === "." && isDigit(src[i + 1] ?? ""))) {
      let j = i;
      while (j < n && isDigit(src[j])) j++;
      if (src[j] === "." ) { j++; while (j < n && isDigit(src[j])) j++; }
      if (j < n && (isWordChar(src[j]) || src[j] === ".")) {
        let k = j;
        while (k < n && (isWordChar(src[k]) || src[k] === ".")) k++;
        throw new LogoError(`Nieprawidłowa liczba „${src.slice(i, k)}”. Liczby zapisuj cyframi, np. 80, 12.5 lub .5.`, pos);
      }
      const text = take(j - i);
      push("number", text, start, pos, { value: Number(text) });
      continue;
    }
    if (isLetter(c) || (c === ":" && isLetter(src[i + 1] ?? ""))) {
      let j = i + (c === ":" ? 1 : 0);
      while (j < n && isWordChar(src[j])) j++;
      let text = src.slice(i, j);
      if (c !== ":" && text.toLowerCase() === "ma" && src[j] === ":") { j++; text += ":"; }
      take(j - i);
      if (c === ":") push("param", text, start, pos, { name: text.slice(1).toLowerCase() });
      else push("word", text, start, pos, { name: text.toLowerCase() });
      continue;
    }
    if (c === '"') {
      let j = i + 1;
      while (j < n && src[j] !== '"' && !/[\s\[\]()]/.test(src[j])) j++;
      const closed = src[j] === '"';
      const end = closed ? j + 1 : j;
      const text = src.slice(i, end);
      const body = closed ? src.slice(i + 1, j) : "";
      if (!closed || !/^#[0-9a-fA-F]{6}$/.test(body)) {
        throw new LogoError(`Nieprawidłowy kolor ${text}. Kolor zapisz jako "#rrggbb", np. "#16866a".`, pos);
      }
      take(end - i);
      push("color", text, start, pos, { name: body.toLowerCase() });
      continue;
    }
    if (c === "<" || c === ">") {
      const two = src.slice(i, i + 2);
      const t = two === "<=" || two === ">=" || two === "<>" ? take(2) : take(1);
      push("cmp", t, start, pos);
      continue;
    }
    if (c === "=") { push("cmp", take(1), start, pos); continue; }
    if ("+-*/".includes(c)) { push("op", take(1), start, pos); continue; }
    const simple: Record<string, TokenType> = { "[": "lbrack", "]": "rbrack", "(": "lparen", ")": "rparen", ",": "comma" };
    if (simple[c]) { push(simple[c], take(1), start, pos); continue; }
    throw new LogoError(`Nieznany znak „${c}”.`, pos);
  }
  if (tokens.length) tokens[tokens.length - 1].lineEnd = true;
  return tokens;
}
EOF

