cat > src/lang/ast.ts <<'EOF'
import type { Token } from "./lexer";

export type Expr =
  | { k: "num"; v: number; tok: Token }
  | { k: "neg"; e: Expr; tok: Token }
  | { k: "bin"; op: string; a: Expr; b: Expr; tok: Token };

export type Stmt =
  | { k: "move"; sign: 1 | -1; arg: Expr; tok: Token }
  | { k: "turn"; axis: "yaw" | "pitch" | "roll"; sign: 1 | -1; arg: Expr; tok: Token }
  | { k: "pen"; down: boolean; tok: Token }
  | { k: "color"; color: string; tok: Token }
  | { k: "width"; arg: Expr; tok: Token }
  | { k: "repeat"; count: Expr; body: Stmt[]; tok: Token; close: Token };

export interface Program { body: Stmt[] }
EOF
cat > src/lang/commands.ts <<'EOF'
/** Every keyword alias mapped to its canonical command. */
const ALIASES: Record<string, string[]> = {
  fd: ["np", "naprzod", "naprzód", "fd", "forward"],
  bk: ["ws", "wstecz", "bk", "back"],
  rt: ["pw", "prawo", "rt", "right"],
  lt: ["lw", "lewo", "lt", "left"],
  pu: ["pod", "podnies", "podnieś", "pu", "penup"],
  pd: ["opu", "opusc", "opuść", "pd", "pendown"],
  color: ["kolor", "color"],
  width: ["grubosc", "grubość", "width"],
  repeat: ["powtorz", "powtórz", "repeat"],
};

export const COMMANDS = new Map<string, string>();
for (const [canon, names] of Object.entries(ALIASES)) for (const n of names) COMMANDS.set(n, canon);
EOF
cat > src/lang/parser.ts <<'EOF'
import { LogoError, LIMITS } from "./errors";
import type { Token } from "./lexer";
import type { Expr, Program, Stmt } from "./ast";
import { COMMANDS } from "./commands";

export type Mode = "2d" | "3d";

const describe = (t: Token) => `„${t.text}”`;

export function parse(tokens: Token[], mode: Mode): Program {
  let p = 0;
  let depth = 0;
  const peek = () => tokens[p];
  const last = () => tokens[tokens.length - 1];

  function missing(cmd: Token, what: string): never {
    const t = peek();
    if (!t) throw new LogoError(`Polecenie ${describe(cmd)} wymaga argumentu: ${what}.`, cmd);
