import { LogoError, LIMITS } from "./errors";
import type { Expr, Program, Stmt } from "./ast";
import type { Token } from "./lexer";

export type Vec = [number, number, number];
export interface Segment { from: Vec; to: Vec; color: string; width: number }

export interface TurtleState {
  pos: Vec; heading: Vec; right: Vec; up: Vec;
  penDown: boolean; color: string; width: number;
}

export const initialTurtle = (): TurtleState => ({
  pos: [0, 0, 0], heading: [0, 1, 0], right: [1, 0, 0], up: [0, 0, 1],
  penDown: true, color: "#16866a", width: 3,
});

/** Step event yielded before each executed command. */
export interface StepEvent { tok: Token }

function trig(deg: number): [number, number] {
  const m = ((deg % 360) + 360) % 360;
  if (m === 0) return [1, 0];
  if (m === 90) return [0, 1];
  if (m === 180) return [-1, 0];
  if (m === 270) return [0, -1];
  const r = (deg * Math.PI) / 180;
  return [Math.cos(r), Math.sin(r)];
}

/** Rotate a towards b by deg: a' = a cos + b sin, b' = b cos - a sin. */
function rotate(a: Vec, b: Vec, deg: number): [Vec, Vec] {
  const [c, s] = trig(deg);
  const a2: Vec = [a[0] * c + b[0] * s, a[1] * c + b[1] * s, a[2] * c + b[2] * s];
  const b2: Vec = [b[0] * c - a[0] * s, b[1] * c - a[1] * s, b[2] * c - a[2] * s];
  return [a2, b2];
}

export class Machine {
  turtle = initialTurtle();
  segments: Segment[] = [];
  ops = 0;
  frames = 0;

  constructor(private program: Program) {}

  private op(tok: Token) {
    if (++this.ops > LIMITS.operations) {
      throw new LogoError(`Przekroczono limit ${LIMITS.operations.toLocaleString("pl-PL")} wykonanych operacji.`, tok);
    }
  }

  private eval(e: Expr): number {
    let v: number;
    switch (e.k) {
      case "num": return e.v;
      case "neg": v = -this.eval(e.e); break;
      case "bin": {
        const a = this.eval(e.a), b = this.eval(e.b);
        if (e.op === "/" && b === 0) throw new LogoError("Dzielenie przez zero.", e.tok);
        v = e.op === "+" ? a + b : e.op === "-" ? a - b : e.op === "*" ? a * b : a / b;
        break;
      }
    }
    if (!Number.isFinite(v)) throw new LogoError("Wynik obliczenia nie jest skończoną liczbą.", e.tok);
    return v;
  }

  /** Evaluate a whole argument; errors are reported at the argument's first token. */
  private arg(e: Expr): number {
    try { return this.eval(e); }
    catch (err) {
      if (err instanceof LogoError) throw new LogoError(err.message, e.tok);
      throw err;
    }
  }

  private integerArg(e: Expr, min: number, max: number, what: string): number {
    const v = this.arg(e);
    if (!Number.isInteger(v) || v < min || v > max) {
      throw new LogoError(`${what} musi być liczbą całkowitą od ${min} do ${max}, a wynosi ${fmt(v)}.`, e.tok);
    }
    return v;
