    const t = this.turtle;
    if (to.some((c) => Math.abs(c) > LIMITS.coordinate)) {
      throw new LogoError(`Żółw wyszedłby poza obszar rysowania (±${LIMITS.coordinate.toLocaleString("pl-PL")}).`, tok);
