import { LogoError } from "./errors";
import { tokenize } from "./lexer";
import { parse, type Mode } from "./parser";
import { Machine, type Segment } from "./exec";

export type { Mode } from "./parser";
export type { Segment } from "./exec";

export interface RunError { message: string; line: number; column: number }
export interface RunResult { segments: Segment[]; error: RunError | null }

const toError = (e: unknown): RunError => {
  if (e instanceof LogoError) return { message: e.message, line: e.line, column: e.column };
  throw e;
};

/** Parse and validate a program, or throw a LogoError. */
export function compile(source: string, mode: Mode) {
  return parse(tokenize(source), mode);
}

/** Interpret a whole program at once. */
export function run(source: string, mode: Mode): RunResult {
  let machine: Machine;
  try { machine = new Machine(compile(source, mode)); }
  catch (e) { return { segments: [], error: toError(e) }; }
  try {
    const it = machine.run();
    while (!it.next().done);
    return { segments: machine.segments, error: null };
  } catch (e) {
    return { segments: machine.segments, error: toError(e) };
  }
}
