  private turn(axis: "yaw" | "pitch" | "roll", deg: number) {
    const t = this.turtle;
    if (axis === "yaw") [t.heading, t.right] = rotate(t.heading, t.right, deg);
    else if (axis === "pitch") [t.heading, t.up] = rotate(t.heading, t.up, deg);
    else [t.up, t.right] = rotate(t.up, t.right, deg);
  }

  *run(): Generator<StepEvent, void, void> {
    yield* this.block(this.program.body);
  }

  private *block(body: Stmt[]): Generator<StepEvent, void, void> {
    for (const s of body) yield* this.stmt(s);
  }

  private *stmt(s: Stmt): Generator<StepEvent, void, void> {
    yield { tok: s.tok };
    this.op(s.tok);
    const t = this.turtle;
    switch (s.k) {
      case "move": this.move(s.sign * this.arg(s.arg), s.tok); break;
      case "turn": this.turn(s.axis, s.sign * this.arg(s.arg)); break;
      case "pen": t.penDown = s.down; break;
      case "color": t.color = s.color; break;
      case "width": t.width = this.integerArg(s.arg, 1, 12, "Grubość"); break;
