test("niech assigns and reassigns variables, legacy :name works, names ignore case", () => {
  expect(dist("niech Bok 30\nniech bok bok + 10\nnp :BOK")).toBe(40);
});

test("top-level variables may be declared after their use but must be assigned before reading", () => {
  const r = run("np 10\nnp x\nniech x 5", "2d");
  expect(r.segments.length).toBe(1);
  expect(r.error).toEqual({ message: expect.any(String), line: 2, column: 4 });
});

test("an undeclared name is a parse-time error", () => {
  expect(run("np 10\nnp y + 1", "2d")).toEqual({ segments: [], error: { message: expect.any(String), line: 2, column: 4 } });
});

test("nrpowt counts iterations of the innermost repeat from 1", () => {
  const r = run("powtorz 2 [powtorz 3 [np nrpowt]]", "2d");
  expect(r.segments.map((s) => s.to[1] - s.from[1])).toEqual([1, 2, 3, 1, 2, 3]);
});

