cat >> tests/interpreter.test.ts <<'EOF'

const WIELOKATY = `; Jedna procedura, wiele figur: kąt liczy się sam.
oto wielokąt ma: boki, bok
  powtorz boki [np bok pw 360 / boki]
już

grubosc 2
niech n 3
powtorz 7 [
  wielokąt n 60
  niech n n + 1
  pw 360 / 7
]`;

test("wielokaty calls a procedure with computed arguments", () => {
  const r = run(WIELOKATY, "2d");
  expect(r.error).toBeNull();
  expect(r.segments.length).toBe(3 + 4 + 5 + 6 + 7 + 8 + 9);
});

test("procedures may be defined after use, with legacy headers and expression arguments", () => {
  const r = run("kwadrat 40 * 2 90\noto kwadrat :bok :kąt\n  powtorz 4 [np :bok pw kąt]\nend", "2d");
  expect(r.error).toBeNull();
  expect(r.segments.length).toBe(4);
  expect(r.segments[0].to).toEqual([0, 80, 0]);
});

test("a parameter may share its name with a procedure", () => {
  const r = run("oto a ma: a\n  jeśli a > 0 [np a a a - 1]\njuż\na 3", "2d");
  expect(r.segments.map((s) => s.to[1])).toEqual([3, 5, 6]);
});

test("stop inside a repeat ends the whole procedure call", () => {
  const r = run("oto f\n powtorz 10 [np 1 jeśli nrpowt = 3 [stop]]\n np 100\njuż\nf\nnp 5", "2d");
  expect(r.segments.map((s) => s.to[1])).toEqual([1, 2, 3, 8]);
});

test("stop at top level ends the program", () => {
  expect(run("np 1\nstop\nnp 2", "2d").segments.length).toBe(1);
});

test("niech inside a procedure is local and shadows the global for the rest of the call", () => {
  const r = run("niech x 10\noto f\n np x\n niech x 1\n np x\njuż\nf\nnp x", "2d");
  expect(r.segments.map((s) => s.to[1] - s.from[1])).toEqual([10, 1, 10]);
});

test("procedure-call errors are reported at parse time with positions", () => {
  const cases: [string, number, number][] = [
    ["oto f ma: a\n np a\njuż\nnp 5\nf", 5, 1],               // too few arguments
    ["oto f\n powtorz 2 [np 1]\njuż\nf 3", 4, 3],              // too many: stray value
    ["oto f\n np 1\n", 1, 1],                                  // missing już
    ["powtorz 2 [\noto f\njuż\n]", 2, 1],                      // definition inside a body
    ["oto f\njuż\noto f\njuż", 3, 5],                          // defined twice
    ["oto f\n np nrpowt\njuż\npowtorz 2 [f]", 2, 5],          // nrpowt not lexically in a repeat
    ["oto f\n np b\njuż\nniech c 1", 2, 5],                   // name not visible in procedure
  ];
  for (const [src, line, column] of cases) {
    expect({ src, ...run(src, "2d") }).toEqual({ src, segments: [], error: { message: expect.any(String), line, column } });
  }
});

test("drzewo recursion draws a symmetric tree", () => {
  const r = run(`oto gałąź ma: dł
  jeśli dł < 6 [stop]
  jeżeli dł > 30 [kolor "#6b4f2a" grubosc 3] [kolor "#2f8f4e" grubosc 1]
  np dł
  lw 25
  gałąź dł * 0.7
  pw 50
  gałąź dł * 0.7
  lw 25
  pod ws dł opu
już

pod ws 120 opu
gałąź 90`, "2d");
  expect(r.error).toBeNull();
  expect(r.segments.length).toBe(511);
  expect(r.segments[0]).toEqual({ from: [0, -120, 0], to: [0, -30, 0], color: "#6b4f2a", width: 3 });
});
EOF
