cat >> tests/interpreter.test.ts <<'EOF'

const near = (v: number[], w: number[]) => expect(v.map((x) => Math.round(x * 1e6) / 1e6 + 0)).toEqual(w);

test("gora 90 heads along the former up vector", () => {
  const r = run("gora 90 np 10 dol 90 np 5", "3d");
  near(r.segments[0].to, [0, 0, 10]);
  near(r.segments[1].to, [0, 5, 10]);
});

test("pp 90 makes up the former right, so a right turn then heads down", () => {
  const r = run("pp 90 pw 90 np 10", "3d");
  near(r.segments[0].to, [0, 0, -10]);
  const l = run("pl 90 pw 90 np 10", "3d");
  near(l.segments[0].to, [0, 0, 10]);
});

test("schody climbs six steps", () => {
  const r = run("powtorz 6 [\n  np 35\n  gora 90\n  np 20\n  dol 90\n]", "3d");
  expect(r.segments.length).toBe(12);
  near(r.segments[11].to, [0, 210, 120]);
});

test("pitch and roll commands are parse-time errors in 2D", () => {
  for (const cmd of ["gora", "góra", "dol", "dół", "pp", "pl", "pitchup", "rollleft"]) {
    expect(run(`np 10\n  ${cmd} 30`, "2d")).toEqual({ segments: [], error: { message: expect.any(String), line: 2, column: 3 } });
  }
});

test("flat programs draw identically in 2D and 3D", () => {
  const src = "powtorz 7 [np 33.3 pw 51.4 ws 5 lw 3]";
  expect(run(src, "3d")).toEqual(run(src, "2d"));
});

test("dom draws back to the origin and resets orientation, keeping pen settings", () => {
  const r = run('kolor "#ff0000" pw 90 np 10 dom np 5', "2d");
  expect(r.segments.map((s) => [s.from, s.to, s.color])).toEqual([
    [[0, 0, 0], [10, 0, 0], "#ff0000"],
    [[10, 0, 0], [0, 0, 0], "#ff0000"],
    [[0, 0, 0], [0, 5, 0], "#ff0000"],
  ]);
});

test("czyść forgets earlier segments only", () => {
  const r = run("np 10 czyść pw 90 np 5", "2d");
  expect(r.segments).toEqual([{ from: [0, 10, 0], to: [5, 10, 0], color: "#16866a", width: 3 }]);
});

test("a run-time error after czyść keeps the segments drawn since", () => {
  const r = run("np 10 czysc np 5\nnp 1 / 0", "2d");
  expect(r.segments.length).toBe(1);
  expect(r.error).toMatchObject({ line: 2, column: 4 });
});
EOF
