input.command:
cat >> tests/interpreter.test.ts <<'EOF'

const err = (src: string, mode: "2d" | "3d" = "2d") => run(src, mode).error;

test("literal widths and repeat counts are validated before anything is drawn", () => {
  for (const [src, col] of [["np 5 grubosc 13", 14], ["np 5 grubosc 2.5", 14], ["np 5 grubosc 0", 14],
    ["np 5 powtorz 10001 [np 1]", 14], ["np 5 powtorz 1.5 [np 1]", 14], ["np 5 powtorz -1 [np 1]", 14],
    ["np 5 grubosc (4 + 10)", 14]] as const) {
    expect(run(src, "2d")).toEqual({ segments: [], error: { message: expect.any(String), line: 1, column: col } });
  }
});

test("computed widths and counts are checked at run time and keep the drawing", () => {
  const r = run("niech g 20\nnp 5\ngrubosc g - 1", "2d");
  expect(r.segments.length).toBe(1);
  expect(r.error).toMatchObject({ line: 3, column: 9 });
  expect(err("niech n 2.5\nnp 1\npowtorz n * 1 [np 1]")).toMatchObject({ line: 3, column: 9 });
});

test("division by zero is reported at the first token of the argument", () => {
  expect(run("np 3\nnp 5 + 1 / 0", "2d")).toEqual({
    segments: [{ from: [0, 0, 0], to: [0, 3, 0], color: "#16866a", width: 3 }],
    error: { message: expect.stringContaining("zero"), line: 2, column: 4 },
  });
});

test("comparisons are exact", () => {
  expect(run("jeśli 0.1 + 0.2 = 0.3 [np 10]", "2d")).toEqual({ segments: [], error: null });
  expect(run("jeżeli 1 <> 1 [np 1] [np 2]", "2d").segments[0].to[1]).toBe(2);
});

test("missing arguments are reported where the argument should start", () => {
  expect(err("powtorz 2 [np]")).toMatchObject({ line: 1, column: 14 });
  expect(err("np 5\nnp")).toMatchObject({ line: 2, column: 1 });
  expect(err("np (2 + )")).toMatchObject({ line: 1, column: 9 });
  expect(err('kolor "#12345"')).toMatchObject({ line: 1, column: 7 });
  expect(err("kolor 5")).toMatchObject({ line: 1, column: 7 });
});

test("unbalanced brackets and parentheses are errors", () => {
  expect(err("powtorz 2 [np 1")).toMatchObject({ line: 1, column: 11 });
  expect(err("np 1 ]")).toMatchObject({ line: 1, column: 6 });
  expect(err("np (1 + 2")).toMatchObject({ line: 1, column: 4 });
  expect(err("np 1 + 2)")).toMatchObject({ line: 1, column: 9 });
});

test("a stray value where a command is expected is reported at that value", () => {
  expect(err("np 10 20")).toMatchObject({ line: 1, column: 7 });
  expect(err("hop 10")).toMatchObject({ line: 1, column: 1 });
});

test("the operation limit counts commands and finished iterations", () => {
  expect(err("powtorz 4999 [np 0]")).toBeNull();
  const r = run("powtorz 5000 [np 0]", "2d");
  expect(r.error?.message).toContain("operacji");
});

test("at most 32 procedure and repeat frames may be active", () => {
  const r = run("oto f ma: n\n np 1\n f n + 1\njuż\nf 1", "2d");
  expect(r.segments.length).toBe(32);
  expect(r.error).toMatchObject({ line: 3, column: 2 });
});

test("coordinates must stay within 100000", () => {
  expect(run("np 100000", "2d").error).toBeNull();
  expect(run("np 5\nws 100001", "2d")).toMatchObject({ segments: [{}], error: { line: 2, column: 1 } });
});

test("bracket nesting is limited to 32", () => {
  const ok = "powtorz 1 [".repeat(31) + "np 1" + "]".repeat(31);
  expect(err(ok)).toBeNull();
  const deep = "jeśli 1 = 1 [".repeat(33) + "np 1" + "]".repeat(33);
  expect(err(deep)).toMatchObject({ line: 1, column: 32 * 13 + 13 });
});

test("source size and token count are limited", () => {
  expect(err("np 1 ".repeat(5000))).toBeNull();
  expect(err("np 1 ".repeat(5000) + "pw")).toMatchObject({ line: 1, column: 25001 });
  expect(err(";".repeat(50001))?.message).toContain("50");
});
EOF
