import { test, expect } from "bun:test";
import { run } from "../src/lang";
import { EXAMPLES } from "../src/examples";

const expected: Record<string, [string, number]> = {
  kwadrat: ["2d", 4], gwiazda: ["2d", 5], rozeta: ["2d", 48], spirala: ["2d", 90],
  wielokaty: ["2d", 42], drzewo: ["2d", 255], sniezynka: ["2d", 768],
  schody: ["3d", 12], szescian: ["3d", 17], pierscien: ["3d", 36], kula: ["3d", 432],
  helisa: ["3d", 240], drzewo3d: ["3d", 121],
};

test("all thirteen standard programs ship in their modes", () => {
  expect(EXAMPLES.map((e) => [e.id, e.mode])).toEqual(Object.entries(expected).map(([id, [m]]) => [id, m]));
});

for (const ex of EXAMPLES) {
  test(`example ${ex.id} runs without error`, () => {
    const r = run(ex.source, ex.mode);
    expect(r.error).toBeNull();
    expect(r.segments.length).toBe(expected[ex.id][1]);
  });
}

test("the kwadrat example is shipped verbatim", () => {
  expect(EXAMPLES[0].source).toBe('; Cztery boki, cztery skręty.\nkolor "#16866a"\ngrubosc 3\npowtorz 4 [\n  np 120\n  pw 90\n]\n');
});

test("the pierscien ring is tilted 30 degrees and closes", () => {
  const r = run(EXAMPLES.find((e) => e.id === "pierscien")!.source, "3d");
  const end = r.segments[35].to;
  expect(Math.hypot(...end)).toBeLessThan(1e-9);
  const top = Math.max(...r.segments.map((s) => s.to[2]));
  expect(top).toBeGreaterThan(0);
});
