import { test, expect } from "bun:test";
import { createController } from "../src/controller";
import { run } from "../src/lang";

/** A manual frame scheduler standing in for requestAnimationFrame. */
function manualFrames() {
  let queue: (() => void)[] = [];
  return {
    schedule: (fn: () => void) => { queue.push(fn); return () => { queue = queue.filter((f) => f !== fn); }; },
    frame() { const q = queue; queue = []; q.forEach((f) => f()); },
    flush() { for (let i = 0; i < 100000 && queue.length; i++) this.frame(); },
    get pending() { return queue.length; },
  };
}

const SQUARE = 'kolor "#123456"\npowtorz 4 [\n np 10\n pw 90\n]';

test("running to the end produces the interpreter's drawing", () => {
  const frames = manualFrames();
  const c = createController({ schedule: frames.schedule });
  c.load(SQUARE, "2d");
  c.setSpeed(1);
  c.run();
  expect(c.state().status).toBe("running");
  frames.flush();
  expect(c.state().status).toBe("done");
  expect(c.state().segments).toEqual(run(SQUARE, "2d").segments);
});

test("stepping executes one command at a time and reports its line", () => {
  const c = createController({ schedule: manualFrames().schedule });
  c.load(SQUARE, "2d");
  c.step();
  expect(c.state()).toMatchObject({ status: "paused", current: { line: 1, column: 1 }, segments: [] });
  c.step(); // powtorz
  c.step(); // np 10
  expect(c.state().current).toEqual({ line: 3, column: 2 });
  expect(c.state().segments.length).toBe(1);
  expect(c.state().turtle.pos).toEqual([0, 10, 0]);
});

test("pause halts an animated run and resume finishes it", () => {
  const frames = manualFrames();
  const c = createController({ schedule: frames.schedule });
  c.load(SQUARE, "2d");
  c.setSpeed(1);
  c.run();
  frames.frame(); frames.frame(); frames.frame();
  c.pause();
  frames.flush();
  expect(c.state().status).toBe("paused");
  expect(c.state().segments.length).toBe(1);
  c.resume();
  frames.flush();
  expect(c.state()).toMatchObject({ status: "done" });
  expect(c.state().segments.length).toBe(4);
});

test("reset forgets the drawing and returns the turtle home", () => {
  const c = createController({ schedule: manualFrames().schedule });
  c.load(SQUARE, "2d");
  c.runToEnd();
  c.reset();
  expect(c.state()).toMatchObject({ status: "idle", segments: [], current: null, error: null });
  expect(c.state().turtle.pos).toEqual([0, 0, 0]);
});

test("a parse error draws nothing and a run-time error keeps the drawing", () => {
  const c = createController({ schedule: manualFrames().schedule });
  c.load("np 10\nnp (", "2d");
  c.runToEnd();
  expect(c.state()).toMatchObject({ status: "error", segments: [], error: { line: 2, column: 5 } });
  c.load("np 10\nnp 1 / 0", "2d");
  c.runToEnd();
  expect(c.state()).toMatchObject({ status: "error", error: { line: 2, column: 4 } });
  expect(c.state().segments.length).toBe(1);
});

test("loading new source while running stops the old run", () => {
  const frames = manualFrames();
  const c = createController({ schedule: frames.schedule });
  c.load(SQUARE, "2d");
  c.setSpeed(1);
  c.run();
  frames.frame();
  c.load("np 5", "2d");
  expect(c.state().status).toBe("idle");
  expect(frames.pending).toBe(0);
  c.runToEnd();
  expect(c.state().segments.length).toBe(1);
});

test("running again after finishing starts from scratch", () => {
  const c = createController({ schedule: manualFrames().schedule });
  c.load(SQUARE, "2d");
  c.runToEnd();
  c.runToEnd();
  expect(c.state().segments.length).toBe(4);
});
EOF
