import { compile, type Mode, type RunError, type Segment } from "./lang";
import { LogoError } from "./lang/errors";
import { Machine, initialTurtle, type StepEvent, type TurtleState } from "./lang/exec";

export type Status = "idle" | "running" | "paused" | "done" | "error";

export interface ControllerState {
  status: Status;
  segments: Segment[];
  turtle: TurtleState;
  /** Position of the command executed most recently. */
  current: { line: number; column: number } | null;
  error: RunError | null;
  mode: Mode;
}

export interface ControllerOptions {
  /** Schedules fn for the next animation frame; returns a cancel function. */
  schedule?: (fn: () => void) => () => void;
  onChange?: (s: ControllerState) => void;
}

const rafSchedule = (fn: () => void) => {
  const id = requestAnimationFrame(fn);
  return () => cancelAnimationFrame(id);
};

/** Commands executed per animation frame at each speed setting (1–10). */
export const SPEEDS = [1, 1, 2, 4, 8, 16, 40, 100, 300, 1000, Infinity];

export function createController(opts: ControllerOptions = {}) {
  const schedule = opts.schedule ?? rafSchedule;
  let source = "";
  let mode: Mode = "2d";
  let speed = 5;
  let machine: Machine | null = null;
  let it: Generator<StepEvent, void, void> | null = null;
  let cancel: (() => void) | null = null;
  let st: ControllerState = fresh();

  function fresh(): ControllerState {
    return { status: "idle", segments: [], turtle: initialTurtle(), current: null, error: null, mode };
  }

  const emit = () => opts.onChange?.(state());

  function state(): ControllerState {
    if (machine) {
      st.segments = machine.segments;
      st.turtle = machine.turtle;
    }
    return { ...st, segments: st.segments.slice(), turtle: { ...st.turtle } };
  }

  function stopTimer() { cancel?.(); cancel = null; }

  /** Prepare a fresh execution if none is in progress. Returns false on a parse error. */
  function ensureStarted(): boolean {
    if (it && (st.status === "paused" || st.status === "running")) return true;
    stopTimer();
    machine = null; it = null;
    st = fresh();
    try {
      machine = new Machine(compile(source, mode));
      it = machine.run();
      return true;
    } catch (e) {
      if (!(e instanceof LogoError)) throw e;
      st.status = "error";
      st.error = { message: e.message, line: e.line, column: e.column };
      return false;
    }
  }

  /** Execute up to n commands. */
  function advance(n: number) {
    if (!it) return;
    try {
      for (let i = 0; i < n; i++) {
        const r = it.next();
        if (r.done) { st.status = "done"; st.current = null; it = null; stopTimer(); return; }
        st.current = { line: r.value.tok.line, column: r.value.tok.column };
      }
    } catch (e) {
      if (!(e instanceof LogoError)) throw e;
      st.status = "error";
      st.error = { message: e.message, line: e.line, column: e.column };
      it = null;
      stopTimer();
    }
  }

  function loop() {
    cancel = null;
    if (st.status !== "running") return;
    advance(SPEEDS[speed]);
    if (st.status === "running") cancel = schedule(loop);
    emit();
  }

  return {
    state,
    load(src: string, m: Mode) {
      stopTimer();
      source = src; mode = m;
      machine = null; it = null;
      st = fresh();
      emit();
    },
    setSpeed(s: number) { speed = Math.max(1, Math.min(10, Math.round(s))); },
    getSpeed: () => speed,
    run() {
      if (st.status === "running") return;
      if (!ensureStarted()) return emit();
      st.status = "running";
      if (speed >= 10) { advance(Infinity); return emit(); }
      cancel = schedule(loop);
      emit();
    },
    runToEnd() {
      if (!ensureStarted()) return emit();
      st.status = "running";
      advance(Infinity);
      emit();
    },
    step() {
      if (!ensureStarted()) return emit();
      stopTimer();
      st.status = "paused";
      advance(1);
      emit();
    },
    pause() {
      if (st.status !== "running") return;
      stopTimer();
      st.status = "paused";
      emit();
    },
    resume() {
      if (st.status !== "paused") return;
      st.status = "running";
      cancel = schedule(loop);
      emit();
    },
    reset() {
      stopTimer();
      machine = null; it = null;
      st = fresh();
      emit();
    },
  };
}

export type Controller = ReturnType<typeof createController>;
