import { test, expect } from "bun:test";
import { CHALLENGES, checkChallenge } from "../src/challenges";

const byId = (id: string) => CHALLENGES.find((c) => c.id === id)!;

test("there are at least five challenges with 2D and 3D tasks", () => {
  expect(CHALLENGES.length).toBeGreaterThanOrEqual(5);
  expect(new Set(CHALLENGES.map((c) => c.mode))).toEqual(new Set(["2d", "3d"]));
});

test("a square drawn another way still passes", () => {
  const r = checkChallenge(byId("kwadrat"), "pod np 50 opu\npowtorz 2 [np 50 np 50 lw 90 np 100 lw 90]");
  expect(r).toEqual({ pass: true, reason: expect.any(String) });
});

test("a square of the wrong size fails with a reason", () => {
  const r = checkChallenge(byId("kwadrat"), "powtorz 4 [np 80 pw 90]");
  expect(r.pass).toBe(false);
  expect(r.reason).toMatch(/rozmiar|wymiar/i);
});

test("a program with an error fails and names the line", () => {
  const r = checkChallenge(byId("kwadrat"), "powtorz 4 [np 100 pw]");
  expect(r.pass).toBe(false);
  expect(r.reason).toContain("1");
});

test("an incomplete drawing fails", () => {
  const r = checkChallenge(byId("kwadrat"), "powtorz 3 [np 100 pw 90]");
  expect(r.pass).toBe(false);
});

test("an empty drawing fails", () => {
  expect(checkChallenge(byId("kwadrat"), "; nic").pass).toBe(false);
});

test("every challenge's own model solution passes", () => {
  for (const c of CHALLENGES) expect({ id: c.id, ...checkChallenge(c, c.solution) }).toMatchObject({ id: c.id, pass: true });
});

test("a cube challenge in 3D accepts a cube built differently", () => {
  const cube = "powtorz 4 [np 80 pw 90]\ngora 90 np 80 dol 90\npowtorz 4 [np 80 pw 90]\npowtorz 4 [np 80 dol 90 np 80 pod ws 80 opu gora 90 pw 90]";
  expect(checkChallenge(byId("szescian"), cube).pass).toBe(true);
  expect(checkChallenge(byId("szescian"), "powtorz 4 [np 80 pw 90]").pass).toBe(false);
});
EOF
