    task: "Narysuj dwa kwadraty o boku 60 stojące obok siebie, z przerwą 40 między nimi.",
    hint: "Podnieś pisak (pod), przejdź dalej i opuść go (opu).",
    solution: "powtorz 4 [np 60 pw 90]\npw 90 pod np 100 opu lw 90\npowtorz 4 [np 60 pw 90]",
  },
  {
    id: "gwiazda", title: "Gwiazda", mode: "2d",
    task: "Narysuj pięcioramienną gwiazdę o ramieniu 150.",
    hint: "Kąt gwiazdy to 144 stopnie.",
