  },
  {
    id: "szescian", title: "Sześcian 80", mode: "3d",
    task: "W trybie 3D zbuduj sześcian o krawędzi 80.",
    hint: "Dwa kwadraty, jeden nad drugim (gora 90), połączone czterema krawędziami.",
    solution: "powtorz 4 [\n  np 80 pw 90\n  gora 90 np 80 ws 80 dol 90\n]\ngora 90 np 80 dol 90\npowtorz 4 [np 80 pw 90]",
  },
];

const TOL = 2;
type P = [number, number, number];

function samples(segs: Segment[]): P[] {
  const out: P[] = [];
  for (const s of segs) {
    const len = Math.hypot(s.to[0] - s.from[0], s.to[1] - s.from[1], s.to[2] - s.from[2]);
    const n = Math.max(1, Math.ceil(len / TOL));
    for (let i = 0; i <= n; i++) {
      const t = i / n;
      out.push([0, 1, 2].map((k) => s.from[k] + (s.to[k] - s.from[k]) * t) as P);
    }
  }
  return out;
}

function distToSeg(p: P, a: P, b: P): number {
  const ab = [b[0] - a[0], b[1] - a[1], b[2] - a[2]];
  const ap = [p[0] - a[0], p[1] - a[1], p[2] - a[2]];
  const l2 = ab[0] ** 2 + ab[1] ** 2 + ab[2] ** 2;
  const t = l2 ? Math.max(0, Math.min(1, (ap[0] * ab[0] + ap[1] * ab[1] + ap[2] * ab[2]) / l2)) : 0;
  return Math.hypot(ap[0] - ab[0] * t, ap[1] - ab[1] * t, ap[2] - ab[2] * t);
}

function bounds(segs: Segment[]) {
  const min: P = [Infinity, Infinity, Infinity], max: P = [-Infinity, -Infinity, -Infinity];
  for (const s of segs) for (const p of [s.from, s.to]) for (let k = 0; k < 3; k++) {
    min[k] = Math.min(min[k], p[k]); max[k] = Math.max(max[k], p[k]);
  }
  return { min, max, size: [0, 1, 2].map((k) => max[k] - min[k]) as P, center: [0, 1, 2].map((k) => (max[k] + min[k]) / 2) as P };
}

/** Move a drawing so its bounding box is centred at the origin, optionally mirrored left-right. */
function normalize(segs: Segment[], mirror: boolean): [P, P][] {
  const { center } = bounds(segs);
  const f = (p: number[]): P => [(p[0] - center[0]) * (mirror ? -1 : 1), p[1] - center[1], p[2] - center[2]];
  return segs.map((s) => [f(s.from), f(s.to)]);
}

/** How far the drawing a strays from drawing b (largest sample distance). */
function stray(a: [P, P][], b: [P, P][]): { d: number; at: P } {
  let worst = { d: 0, at: [0, 0, 0] as P };
  const segs = a.map(([from, to]) => ({ from, to, color: "", width: 1 }));
  for (const p of samples(segs)) {
    let best = Infinity;
    for (const [x, y] of b) { best = Math.min(best, distToSeg(p, x, y)); if (best <= TOL) break; }
    if (best > worst.d) worst = { d: best, at: p };
  }
  return worst;
}

const n0 = (v: number) => String(Math.round(v)).replace("-0", "0");

/** Compare the program's drawing with the expected one, ignoring position, direction and mirroring. */
export function checkChallenge(c: Challenge, source: string): CheckResult {
  const got = run(source, c.mode);
  if (got.error) return { pass: false, reason: `Błąd w wierszu ${got.error.line}, kolumna ${got.error.column}: ${got.error.message}` };
  if (!got.segments.length) return { pass: false, reason: "Program niczego nie narysował." };
  const want = run(c.solution, c.mode).segments;
  const bw = bounds(want), bg = bounds(got.segments);
  const dims = c.mode === "3d" ? 3 : 2;
  for (let k = 0; k < dims; k++) {
    if (Math.abs(bw.size[k] - bg.size[k]) > TOL) {
      const f = (s: P) => s.slice(0, dims).map(n0).join(" × ");
      return { pass: false, reason: `Rysunek ma inny rozmiar: oczekiwano ok. ${f(bw.size)}, a jest ${f(bg.size)}.` };
    }
  }
  const w = normalize(want, false);
  let best: CheckResult | null = null;
  for (const mirror of [false, true]) {
    const g = normalize(got.segments, mirror);
    const missing = stray(w, g);
    const extra = stray(g, w);
    if (missing.d <= TOL && extra.d <= TOL) return { pass: true, reason: "Brawo! Rysunek zgadza się z zadaniem." };
    if (!best) {
      best = missing.d > TOL
        ? { pass: false, reason: "Brakuje części rysunku: nie wszystkie oczekiwane linie zostały narysowane." }
        : { pass: false, reason: "Rysunek ma linie, których nie ma we wzorze." };
    }
  }
  return best!;
}
