import { test, expect } from "bun:test";
import { createWorkspace, shareHash, parseShareHash, toLogoFile, fromLogoFile } from "../src/workspace";
import { EXAMPLES } from "../src/examples";

function memoryStorage(): Storage {
  const m = new Map<string, string>();
  return {
    getItem: (k) => m.get(k) ?? null, setItem: (k, v) => void m.set(k, String(v)),
    removeItem: (k) => void m.delete(k), clear: () => m.clear(), key: (i) => [...m.keys()][i] ?? null,
    get length() { return m.size; },
  };
}

test("each mode's draft survives a reload", () => {
  const storage = memoryStorage();
  const a = createWorkspace({ storage });
  a.edit("np 10");
  a.setMode("3d");
  a.edit("gora 45 np 10");
  const b = createWorkspace({ storage });
  expect([b.mode(), b.source()]).toEqual(["3d", "gora 45 np 10"]);
  b.setMode("2d");
  expect(b.source()).toBe("np 10");
});

test("loading an example asks before replacing an unsaved draft and keeps a backup", () => {
  const asked: string[] = [];
  let answer = false;
  const ws = createWorkspace({ storage: memoryStorage(), confirm: (m) => { asked.push(m); return answer; } });
  ws.edit("moj program");
  expect(ws.openExample("gwiazda")).toBe(false);
  expect(ws.source()).toBe("moj program");
  answer = true;
  expect(ws.openExample("schody")).toBe(true);
  expect(asked.length).toBe(2);
  expect([ws.mode(), ws.source()]).toEqual(["3d", EXAMPLES.find((e) => e.id === "schody")!.source]);
  ws.setMode("2d");
  expect(ws.source()).toBe("moj program");
});

test("loading an example over the same mode's draft can be undone", () => {
  const ws = createWorkspace({ storage: memoryStorage(), confirm: () => true });
  ws.edit("np 77");
  ws.openExample("kwadrat");
  expect(ws.backup()).toBe("np 77");
  ws.restoreBackup();
  expect(ws.source()).toBe("np 77");
});

test("an example replaces another example without asking", () => {
  let asked = 0;
  const ws = createWorkspace({ storage: memoryStorage(), confirm: () => (asked++, false) });
  ws.openExample("kwadrat");
  ws.openExample("gwiazda");
  ws.edit("");
  ws.openExample("rozeta");
  expect(asked).toBe(0);
  expect(ws.source()).toContain("Obróć kwadrat");
});

test("solved challenges are remembered", () => {
  const storage = memoryStorage();
  createWorkspace({ storage }).markSolved("kwadrat");
  expect(createWorkspace({ storage }).solved()).toEqual(["kwadrat"]);
});

test("a share link round-trips the program and mode, including Polish letters", () => {
  const src = "oto gałąź ma: dł\n np dł\njuż\ngałąź 50 ; żółw";
  const hash = shareHash(src, "3d");
  expect(hash.startsWith("#/")).toBe(true);
  expect(hash).not.toMatch(/[\s+/=]/.source === "" ? /x/ : /[\s]/);
  expect(parseShareHash(hash)).toEqual({ source: src, mode: "3d" });
  expect(parseShareHash("#/pomoc")).toBeNull();
});

test(".logo files keep the mode and open back", () => {
  const text = toLogoFile("gora 30 np 5", "3d");
  expect(fromLogoFile(text)).toEqual({ source: "gora 30 np 5", mode: "3d" });
  expect(fromLogoFile("np 5\r\npw 90")).toEqual({ source: "np 5\npw 90", mode: null });
});
