import type { Mode } from "./lang";
import { EXAMPLES } from "./examples";

export interface WorkspaceOptions {
  storage?: Storage | null;
  confirm?: (message: string) => boolean;
}

const KEY = "logomocja:v1:";

/** Drafts per mode, example loading that never silently drops work, and challenge progress. */
export function createWorkspace(opts: WorkspaceOptions = {}) {
  const storage = opts.storage ?? null;
  const confirm = opts.confirm ?? (() => true);
  const get = (k: string) => { try { return storage?.getItem(KEY + k) ?? null; } catch { return null; } };
  const set = (k: string, v: string) => { try { storage?.setItem(KEY + k, v); } catch { /* quota or privacy mode */ } };

  let mode: Mode = get("mode") === "3d" ? "3d" : "2d";
  const drafts: Record<Mode, string> = { "2d": get("draft:2d") ?? EXAMPLES[0].source, "3d": get("draft:3d") ?? "" };

  const isPristine = (src: string) => !src.trim() || EXAMPLES.some((e) => e.source === src);

  const api = {
    mode: () => mode,
    source: (m: Mode = mode) => drafts[m],
    setMode(m: Mode) { mode = m; set("mode", m); },
    edit(src: string) { drafts[mode] = src; set(`draft:${mode}`, src); },
    /** Load a built-in example into its mode. Returns false if the user kept their draft. */
    openExample(id: string): boolean {
      const ex = EXAMPLES.find((e) => e.id === id);
      if (!ex) return false;
      return api.replace(ex.source, ex.mode, `Wczytać przykład „${ex.title}”?`);
    },
    /** Replace the draft of mode m, asking first if it holds unsaved work. */
    replace(src: string, m: Mode, question: string): boolean {
      const current = drafts[m];
      if (current !== src && !isPristine(current)) {
        if (!confirm(`${question} Twój obecny program w trybie ${m.toUpperCase()} zostanie zastąpiony (będzie można go przywrócić).`)) return false;
        set("backup", JSON.stringify({ source: current, mode: m }));
      }
      api.setMode(m);
      api.edit(src);
      return true;
    },
    backup(): string | null {
      try { return JSON.parse(get("backup") ?? "null")?.source ?? null; } catch { return null; }
    },
    restoreBackup(): boolean {
      let b: { source: string; mode: Mode } | null = null;
      try { b = JSON.parse(get("backup") ?? "null"); } catch { /* ignore */ }
      if (!b) return false;
      const replaced = { source: drafts[b.mode], mode: b.mode };
      api.setMode(b.mode);
      api.edit(b.source);
      set("backup", JSON.stringify(replaced));
      return true;
    },
    solved(): string[] {
      try { return JSON.parse(get("solved") ?? "[]"); } catch { return []; }
    },
    markSolved(id: string) {
      const s = api.solved();
      if (!s.includes(id)) set("solved", JSON.stringify([...s, id]));
    },
    getPref: (k: string) => get(`pref:${k}`),
    setPref: (k: string, v: string) => set(`pref:${k}`, v),
  };
  return api;
}

export type Workspace = ReturnType<typeof createWorkspace>;

function toBase64Url(text: string): string {
  const bytes = new TextEncoder().encode(text);
  let bin = "";
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function fromBase64Url(s: string): string {
  const bin = atob(s.replace(/-/g, "+").replace(/_/g, "/"));
  return new TextDecoder("utf-8", { fatal: true }).decode(Uint8Array.from(bin, (c) => c.charCodeAt(0)));
}

/** URL hash encoding a program and its mode: #/p/<mode>/<base64url>. */
export const shareHash = (source: string, mode: Mode) => `#/p/${mode}/${toBase64Url(source)}`;

export function parseShareHash(hash: string): { source: string; mode: Mode } | null {
  const m = /^#\/p\/(2d|3d)\/([A-Za-z0-9_-]*)$/.exec(hash);
  if (!m) return null;
  try { return { mode: m[1] as Mode, source: fromBase64Url(m[2]) }; } catch { return null; }
}

const HEADER = /^; Logomocja, tryb (2d|3d)\r?\n/;

export const toLogoFile = (source: string, mode: Mode) => `; Logomocja, tryb ${mode}\n${source}`;

export function fromLogoFile(text: string): { source: string; mode: Mode | null } {
  const m = HEADER.exec(text);
  const body = (m ? text.slice(m[0].length) : text).replace(/\r\n?/g, "\n").replace(/^﻿/, "");
  return { source: body, mode: m ? (m[1] as Mode) : null };
}
