/** Canvas view of a drawing: a pannable plane in 2D, an orbit camera in 3D. */
export class Viewport {
  mode: Mode = "2d";
  private ctx: CanvasRenderingContext2D;
  private scene: Scene = { segments: [], turtle: null };
  // 2D camera
  private cx = 0; private cy = 0; private scale = 1.5;
  // 3D camera
  private yaw = -62; private pitch = 28; private dist = 600; private target: Vec = [0, 0, 0];
  private pointers = new Map<number, { x: number; y: number }>();
  private pinch = 0;
  private queued = false;
  onViewChange?: () => void;

  constructor(public canvas: HTMLCanvasElement) {
    const ctx = canvas.getContext("2d");
    if (!ctx) throw new Error("Brak obsługi elementu canvas.");
    this.ctx = ctx;
    new ResizeObserver(() => this.render()).observe(canvas);
    this.bindInput();
  }

  setMode(m: Mode) { this.mode = m; this.render(); }
  setScene(segments: Segment[], turtle: TurtleState | null) { this.scene = { segments, turtle }; this.request(); }

  request() {
    if (this.queued) return;
    this.queued = true;
    requestAnimationFrame(() => { this.queued = false; this.render(); });
  }

  private css(name: string) { return getComputedStyle(this.canvas).getPropertyValue(name).trim(); }

  private bounds(): { min: Vec; max: Vec } | null {
    const pts: Vec[] = [];
    for (const s of this.scene.segments) pts.push(s.from, s.to);
    if (this.scene.turtle) pts.push(this.scene.turtle.pos);
    if (!pts.length) return null;
    const min: Vec = [Infinity, Infinity, Infinity], max: Vec = [-Infinity, -Infinity, -Infinity];
    for (const p of pts) for (let k = 0; k < 3; k++) { min[k] = Math.min(min[k], p[k]); max[k] = Math.max(max[k], p[k]); }
    return { min, max };
  }

  /** Frame the whole drawing. */
  fit() {
    const b = this.bounds();
    const { width: w, height: h } = this.size();
    if (!b) { this.resetView(); return; }
    if (this.mode === "2d") {
      this.cx = (b.min[0] + b.max[0]) / 2;
      this.cy = (b.min[1] + b.max[1]) / 2;
      const bw = Math.max(b.max[0] - b.min[0], 20), bh = Math.max(b.max[1] - b.min[1], 20);
      this.scale = Math.min((w - 48) / bw, (h - 48) / bh);
    } else {
      this.target = [0, 1, 2].map((k) => (b.min[k] + b.max[k]) / 2) as Vec;
      const r = Math.max(Math.hypot(b.max[0] - b.min[0], b.max[1] - b.min[1], b.max[2] - b.min[2]) / 2, 20);
      const fov = this.fov();
      const aspect = Math.min(1, w / h);
      this.dist = (r / Math.sin(fov / 2) / aspect) * 1.05;
    }
    this.render();
    this.onViewChange?.();
  }

  resetView() {
    this.cx = 0; this.cy = 0; this.scale = 1.5;
    this.yaw = -62; this.pitch = 28; this.dist = 600; this.target = [0, 0, 0];
    this.render();
    this.onViewChange?.();
  }

  /** True when the whole drawing is inside the visible area. */
  fits(): boolean {
    const b = this.bounds();
    if (!b) return true;
    const { width: w, height: h } = this.size();
    const corners: Vec[] = [];
    for (const x of [b.min[0], b.max[0]]) for (const y of [b.min[1], b.max[1]]) for (const z of [b.min[2], b.max[2]]) corners.push([x, y, z]);
    return corners.every((c) => {
      const p = this.project(c);
      return p && p[0] >= 0 && p[0] <= w && p[1] >= 0 && p[1] <= h;
    });
  }

  zoom(factor: number) {
    if (this.mode === "2d") this.scale = Math.min(500, Math.max(0.002, this.scale * factor));
    else this.dist = Math.min(1e6, Math.max(5, this.dist / factor));
    this.render();
  }

  pan(dx: number, dy: number) {
    if (this.mode === "2d") { this.cx -= dx / this.scale; this.cy += dy / this.scale; }
    else {
      const { r, u } = this.basis();
      const k = (this.dist * Math.tan(this.fov() / 2) * 2) / this.size().height;
      for (let i = 0; i < 3; i++) this.target[i] += (-r[i] * dx + u[i] * dy) * k;
    }
    this.render();
  }

  orbit(dYaw: number, dPitch: number) {
    this.yaw -= dYaw;
    this.pitch = Math.max(-89, Math.min(89, this.pitch + dPitch));
    this.render();
  }

  private size() {
    const r = this.canvas.getBoundingClientRect();
    return { width: Math.max(1, r.width), height: Math.max(1, r.height) };
  }

  private fov() { return 45 * DEG; }

  private eye(): Vec {
    const y = this.yaw * DEG, p = this.pitch * DEG;
    return [this.target[0] + this.dist * Math.cos(p) * Math.cos(y), this.target[1] + this.dist * Math.cos(p) * Math.sin(y), this.target[2] + this.dist * Math.sin(p)];
  }

  private basis() {
    const e = this.eye();
    const f = norm(sub(this.target, e));
    const r = norm(cross(f, [0, 0, 1]));
    const u = cross(r, f);
    return { e, f, r, u };
  }

  /** Camera-space coordinates (x right, y up, z depth). */
  private toCam(p: Vec, b = this.basis()): Vec {
    const v = sub(p, b.e);
    return [dot(v, b.r), dot(v, b.u), dot(v, b.f)];
  }

  private camToScreen(c: Vec): [number, number] {
    const { width: w, height: h } = this.size();
    const focal = h / 2 / Math.tan(this.fov() / 2);
    return [w / 2 + (c[0] / c[2]) * focal, h / 2 - (c[1] / c[2]) * focal];
  }

  project(p: Vec): [number, number] | null {
    const { width: w, height: h } = this.size();
    if (this.mode === "2d") return [w / 2 + (p[0] - this.cx) * this.scale, h / 2 - (p[1] - this.cy) * this.scale];
    const c = this.toCam(p);
    return c[2] > 1e-3 ? this.camToScreen(c) : null;
  }

  /** Project a 3D segment, clipping it against the near plane. */
  private projectSeg(a: Vec, b: Vec, basis = this.basis()): [[number, number], [number, number], number] | null {
    let ca = this.toCam(a, basis), cb = this.toCam(b, basis);
    const near = Math.max(0.5, this.dist * 0.001);
    if (ca[2] < near && cb[2] < near) return null;
    if (ca[2] < near || cb[2] < near) {
      const t = (near - ca[2]) / (cb[2] - ca[2]);
      const m: Vec = [ca[0] + (cb[0] - ca[0]) * t, ca[1] + (cb[1] - ca[1]) * t, near];
      if (ca[2] < near) ca = m; else cb = m;
    }
    return [this.camToScreen(ca), this.camToScreen(cb), (ca[2] + cb[2]) / 2];
  }

  render() {
    const { width: w, height: h } = this.size();
    const dpr = window.devicePixelRatio || 1;
    const cw = Math.round(w * dpr), ch = Math.round(h * dpr);
    if (this.canvas.width !== cw || this.canvas.height !== ch) { this.canvas.width = cw; this.canvas.height = ch; }
    const ctx = this.ctx;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.fillStyle = this.css("--canvas") || "#fff";
    ctx.fillRect(0, 0, w, h);
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    if (this.mode === "2d") this.render2d(w, h); else this.render3d();
  }

  private render2d(w: number, h: number) {
    const ctx = this.ctx;
    // Grid with a step that stays readable at any zoom.
    let step = 10;
    while (step * this.scale < 24) step *= step.toString().startsWith("1") ? 5 : 2;
    while (step * this.scale > 120 && step > 1e-3) step /= 2;
    const x0 = this.cx - w / 2 / this.scale, x1 = this.cx + w / 2 / this.scale;
    const y0 = this.cy - h / 2 / this.scale, y1 = this.cy + h / 2 / this.scale;
    ctx.strokeStyle = this.css("--grid");
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let x = Math.ceil(x0 / step) * step; x <= x1; x += step) { const s = this.project([x, 0, 0])![0]; ctx.moveTo(s, 0); ctx.lineTo(s, h); }
    for (let y = Math.ceil(y0 / step) * step; y <= y1; y += step) { const s = this.project([0, y, 0])![1]; ctx.moveTo(0, s); ctx.lineTo(w, s); }
    ctx.stroke();
    // Origin axes.
    const o = this.project([0, 0, 0])!;
    ctx.strokeStyle = this.css("--axis");
    ctx.lineWidth = 1.25;
    ctx.beginPath();
    ctx.moveTo(0, o[1]); ctx.lineTo(w, o[1]);
    ctx.moveTo(o[0], 0); ctx.lineTo(o[0], h);
    ctx.stroke();
    ctx.fillStyle = this.css("--axis");
    ctx.beginPath(); ctx.arc(o[0], o[1], 3.5, 0, Math.PI * 2); ctx.fill();
    ctx.font = "11px system-ui, sans-serif";
    ctx.fillText("(0, 0)", o[0] + 6, o[1] - 6);

    for (const s of this.scene.segments) {
      const a = this.project(s.from)!, b = this.project(s.to)!;
      ctx.strokeStyle = s.color;
      ctx.lineWidth = s.width;
      ctx.beginPath(); ctx.moveTo(a[0], a[1]); ctx.lineTo(b[0], b[1]); ctx.stroke();
    }
    const t = this.scene.turtle;
    if (t) {
      const L = 16 / this.scale, W = 8 / this.scale;
      const p = t.pos, hd = t.heading, r = t.right;
      const tip = this.project(add(p, scale(hd, L)))!;
      const bl = this.project(add(add(p, scale(hd, -L * 0.35)), scale(r, -W)))!;
      const br = this.project(add(add(p, scale(hd, -L * 0.35)), scale(r, W)))!;
      this.drawMarker([tip, bl, br]);
    }
  }

  private drawMarker(tri: [number, number][], fin?: [[number, number], [number, number]]) {
    const ctx = this.ctx;
    ctx.fillStyle = this.css("--turtle");
    ctx.strokeStyle = this.css("--turtle-edge");
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(...tri[0]); ctx.lineTo(...tri[1]); ctx.lineTo(...tri[2]); ctx.closePath();
    ctx.globalAlpha = 0.85; ctx.fill(); ctx.globalAlpha = 1; ctx.stroke();
    if (fin) {
      ctx.strokeStyle = this.css("--turtle-edge");
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(...fin[0]); ctx.lineTo(...fin[1]); ctx.stroke();
    }
  }

  private render3d() {
    const ctx = this.ctx;
    const basis = this.basis();
    // Ground grid on the XY plane, sized to the drawing.
    const b = this.bounds();
    const extent = Math.max(200, b ? Math.max(...b.min.map(Math.abs), ...b.max.map(Math.abs)) * 1.3 : 200);
    let step = 10;
    while (extent / step > 20) step *= step.toString().startsWith("1") ? 5 : 2;
    const lim = Math.ceil(extent / step) * step;
    ctx.strokeStyle = this.css("--grid");
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let v = -lim; v <= lim; v += step) {
      for (const [a, c] of [[[v, -lim, 0], [v, lim, 0]], [[-lim, v, 0], [lim, v, 0]]] as [Vec, Vec][]) {
        const s = this.projectSeg(a, c, basis);
        if (s) { ctx.moveTo(...s[0]); ctx.lineTo(...s[1]); }
      }
    }
    ctx.stroke();
    const axes: [Vec, string, string][] = [[[1, 0, 0], "--axis-x", "X"], [[0, 1, 0], "--axis-y", "Y"], [[0, 0, 1], "--axis-z", "Z"]];
    ctx.font = "bold 12px system-ui, sans-serif";
    for (const [dir, col, label] of axes) {
      const end = scale(dir, lim * 0.6);
      const s = this.projectSeg([0, 0, 0], end, basis);
      if (!s) continue;
      ctx.strokeStyle = ctx.fillStyle = this.css(col);
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(...s[0]); ctx.lineTo(...s[1]); ctx.stroke();
      ctx.fillText(label, s[1][0] + 4, s[1][1] - 4);
    }
    // Segments, far to near.
    const list: [[number, number], [number, number], number, Segment][] = [];
    for (const seg of this.scene.segments) {
      const s = this.projectSeg(seg.from, seg.to, basis);
      if (s) list.push([s[0], s[1], s[2], seg]);
    }
    list.sort((a, c) => c[2] - a[2]);
    const focal = this.size().height / 2 / Math.tan(this.fov() / 2);
    for (const [a, c, depth, seg] of list) {
      ctx.strokeStyle = seg.color;
      ctx.lineWidth = Math.max(0.75, Math.min(seg.width * 2.5, seg.width * (focal / depth) * 1.6));
      ctx.beginPath(); ctx.moveTo(...a); ctx.lineTo(...c); ctx.stroke();
    }
    const t = this.scene.turtle;
    if (t) {
      const L = this.dist * 0.035, W = L * 0.5;
      const p = t.pos;
      const back = add(p, scale(t.heading, -L * 0.35));
      const pts = [add(p, scale(t.heading, L)), add(back, scale(t.right, -W)), add(back, scale(t.right, W))].map((q) => this.project(q));
      const fin = [this.project(p), this.project(add(p, scale(t.up, L * 0.7)))];
      if (pts.every(Boolean) && fin.every(Boolean)) this.drawMarker(pts as [number, number][], fin as [[number, number], [number, number]]);
    }
  }

  private bindInput() {
    const c = this.canvas;
    c.addEventListener("pointerdown", (e) => {
      c.setPointerCapture(e.pointerId);
      this.pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
      this.pinch = this.pinchDist();
    });
    c.addEventListener("pointermove", (e) => {
      const prev = this.pointers.get(e.pointerId);
      if (!prev) return;
      const dx = e.clientX - prev.x, dy = e.clientY - prev.y;
      this.pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
      if (this.pointers.size >= 2) {
        const d = this.pinchDist();
        if (this.pinch > 0 && d > 0) this.zoom(d / this.pinch);
        this.pinch = d;
        this.pan(dx / 2, dy / 2);
      } else if (this.mode === "3d" && !e.shiftKey && e.buttons !== 4 && e.buttons !== 2) this.orbit(dx * 0.4, dy * 0.4);
      else this.pan(dx, dy);
    });
    const end = (e: PointerEvent) => { this.pointers.delete(e.pointerId); this.pinch = this.pinchDist(); };
    c.addEventListener("pointerup", end);
    c.addEventListener("pointercancel", end);
    c.addEventListener("contextmenu", (e) => e.preventDefault());
    c.addEventListener("wheel", (e) => { e.preventDefault(); this.zoom(Math.exp(-e.deltaY * 0.0015)); }, { passive: false });
    c.addEventListener("keydown", (e) => {
      const k = e.key;
      const s = e.shiftKey ? 60 : 20;
      const handled = true;
      if (k === "+" || k === "=") this.zoom(1.2);
      else if (k === "-" || k === "_") this.zoom(1 / 1.2);
      else if (k.startsWith("Arrow")) {
        const [dx, dy] = k === "ArrowLeft" ? [-1, 0] : k === "ArrowRight" ? [1, 0] : k === "ArrowUp" ? [0, -1] : [0, 1];
        if (this.mode === "3d" && !e.shiftKey) this.orbit(dx * 8, -dy * 8);
        else this.pan(-dx * s, -dy * s);
      } else if (k === "0") this.fit();
      else return;
      if (handled) e.preventDefault();
    });
  }

  private pinchDist() {
    const p = [...this.pointers.values()];
    return p.length >= 2 ? Math.hypot(p[0].x - p[1].x, p[0].y - p[1].y) : 0;
  }

  /** PNG of the current view. */
  toBlob(): Promise<Blob | null> {
    this.render();
    return new Promise((res) => this.canvas.toBlob(res, "image/png"));
  }
}

const sub = (a: Vec, b: Vec): Vec => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const add = (a: Vec, b: Vec): Vec => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
const scale = (a: Vec, k: number): Vec => [a[0] * k, a[1] * k, a[2] * k];
const dot = (a: Vec, b: Vec) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const cross = (a: Vec, b: Vec): Vec => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
const norm = (a: Vec): Vec => { const l = Math.hypot(...a) || 1; return [a[0] / l, a[1] / l, a[2] / l]; };
