import { COMMANDS } from "../lang/commands";

const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

const TOKEN = /(;[^\n]*)|("[^\s\[\]()"]*"?)|(\d+(?:\.\d*)?|\.\d+)|(:?[\p{L}_][\p{L}\p{N}_]*:?)|([\[\]])|([()])|(<=|>=|<>|[-+*/<>=,])/gu;

/** Syntax-highlighted HTML for one line of Logo source. */
export function highlightLine(line: string, procs: Set<string>): string {
  let out = "", last = 0;
  for (const m of line.matchAll(TOKEN)) {
    out += esc(line.slice(last, m.index));
    const [t, comment, str, num, word, brack, paren, op] = m;
    let cls = "";
    if (comment) cls = "c";
    else if (str) cls = /^"#[0-9a-f]{6}"$/i.test(str) ? "s" : "s bad";
    else if (num) cls = "n";
    else if (word) {
      const w = word.toLowerCase();
      if (w === "ma:" ) cls = "k";
      else if (COMMANDS.has(w)) cls = ["to", "end", "repeat", "if", "ifelse", "let", "stop"].includes(COMMANDS.get(w)!) ? "k" : COMMANDS.get(w) === "repcount" ? "v" : "cmd";
      else if (procs.has(w.replace(/^:/, ""))) cls = "p";
      else cls = "v";
    } else if (brack) cls = "b";
    else if (paren) cls = "pa";
    else if (op) cls = "o";
    if (cls === "s" && str) {
      const hex = str.slice(1, 8);
      out += `<span class="tk-s"><span class="swatch" style="--sw:${esc(hex)}"></span>${esc(t)}</span>`;
    } else out += `<span class="tk-${cls.replace(" ", " tk-")}">${esc(t)}</span>`;
    last = m.index! + t.length;
  }
  return out + esc(line.slice(last));
}

export interface Marker { line: number; column: number; message: string }

/** Plain textarea with a highlighted overlay, line numbers, error and execution markers. */
export class Editor {
  readonly textarea: HTMLTextAreaElement;
  private pre: HTMLElement;
  private gutter: HTMLElement;
  private bubble: HTMLElement;
  private error: Marker | null = null;
  private current: number | null = null;
  onInput?: (text: string) => void;

  constructor(root: HTMLElement) {
    root.classList.add("editor");
    root.innerHTML = `
      <div class="ed-gutter" aria-hidden="true"></div>
      <div class="ed-body">
        <pre class="ed-pre" aria-hidden="true"></pre>
        <textarea class="ed-text" spellcheck="false" autocapitalize="off" autocomplete="off" autocorrect="off"
          aria-label="Program w języku Logo" aria-describedby="status-msg"></textarea>
        <div class="ed-bubble" role="presentation" hidden></div>
      </div>`;
    this.gutter = root.querySelector(".ed-gutter")!;
    this.pre = root.querySelector(".ed-pre")!;
    this.textarea = root.querySelector("textarea")!;
    this.bubble = root.querySelector(".ed-bubble")!;
    this.textarea.addEventListener("input", () => {
      this.error = null;
      this.paint();
      this.onInput?.(this.textarea.value);
    });
    this.textarea.addEventListener("scroll", () => this.syncScroll());
    this.textarea.addEventListener("keydown", (e) => {
      // Enter keeps the indentation of the current line.
      if (e.key === "Enter" && !e.ctrlKey && !e.metaKey && !e.shiftKey && !e.altKey) {
        const ta = this.textarea;
        const before = ta.value.slice(0, ta.selectionStart);
        const indent = /[ \t]*/.exec(before.slice(before.lastIndexOf("\n") + 1))![0];
        if (indent) {
          e.preventDefault();
          ta.setRangeText("\n" + indent, ta.selectionStart, ta.selectionEnd, "end");
          ta.dispatchEvent(new Event("input"));
        }
      }
    });
  }

  get value() { return this.textarea.value; }
  set value(v: string) { this.textarea.value = v; this.error = null; this.current = null; this.paint(); }

  setError(m: Marker | null) { this.error = m; this.paint(); }
  setCurrent(line: number | null) {
    if (line === this.current) return;
    this.current = line;
    this.paint();
    if (line !== null) this.reveal(line);
  }

  private reveal(line: number) {
    const lh = this.lineHeight();
    const top = (line - 1) * lh, ta = this.textarea;
    if (top < ta.scrollTop || top + lh > ta.scrollTop + ta.clientHeight) ta.scrollTop = Math.max(0, top - ta.clientHeight / 2);
  }

  private lineHeight() { return parseFloat(getComputedStyle(this.textarea).lineHeight) || 20; }

  paint() {
    const text = this.textarea.value;
    const lines = text.split("\n");
    const procs = new Set<string>();
    for (const m of text.matchAll(/^[ \t]*(?:oto|to)[ \t]+([\p{L}_][\p{L}\p{N}_]*)/gimu)) procs.add(m[1].toLowerCase());
    const err = this.error;
    this.pre.innerHTML = lines.map((l, i) => {
      const n = i + 1;
      let html: string;
      if (err && err.line === n) {
        const c = Math.min(err.column - 1, l.length);
        const rest = l.slice(c);
        const len = Math.max(1, (/^\S+/.exec(rest)?.[0] ?? " ").length);
        html = highlightLine(l.slice(0, c), procs) + `<span class="ed-err">${highlightLine(rest.slice(0, len) || " ", procs)}</span>` + highlightLine(rest.slice(len), procs);
      } else html = highlightLine(l, procs);
      const cls = n === this.current ? "ln cur" : err?.line === n ? "ln bad" : "ln";
      return `<span class="${cls}">${html || " "}</span>`;
    }).join("\n") + "\n";
    this.gutter.innerHTML = lines.map((_, i) => {
      const n = i + 1;
      const cls = err?.line === n ? "g bad" : n === this.current ? "g cur" : "g";
      return `<span class="${cls}">${n}</span>`;
    }).join("");
    if (err) {
      this.bubble.hidden = false;
      this.bubble.textContent = `Wiersz ${err.line}, kolumna ${err.column}: ${err.message}`;
      const lh = this.lineHeight();
      this.bubble.style.setProperty("--top", `${err.line * lh + 6}px`);
      this.bubble.style.setProperty("--left", `calc(${err.column - 1}ch + 12px)`);
    } else this.bubble.hidden = true;
    this.syncScroll();
  }

  private syncScroll() {
    const ta = this.textarea;
    this.pre.style.transform = `translate(${-ta.scrollLeft}px, ${-ta.scrollTop}px)`;
    this.bubble.style.translate = `${-ta.scrollLeft}px ${-ta.scrollTop}px`;
    this.gutter.scrollTop = ta.scrollTop;
  }

  focus() { this.textarea.focus(); }

  /** Put the caret at a line and column. */
  goTo(line: number, column: number) {
    const lines = this.textarea.value.split("\n");
    let off = 0;
    for (let i = 0; i < line - 1 && i < lines.length; i++) off += lines[i].length + 1;
    off += column - 1;
    this.textarea.focus();
    this.textarea.setSelectionRange(off, off);
    this.reveal(line);
  }
}
