import type { Mode, Segment } from "../lang";

/** Draw a small static preview of a drawing, fitted to the canvas. */
export function drawThumb(canvas: HTMLCanvasElement, segments: Segment[], mode: Mode) {
  const dpr = window.devicePixelRatio || 1;
  const w = canvas.clientWidth || 160, h = canvas.clientHeight || 120;
  canvas.width = w * dpr; canvas.height = h * dpr;
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, w, h);
  const yaw = (-62 * Math.PI) / 180, pitch = (28 * Math.PI) / 180;
  // Orthographic view matching the default 3D camera.
  const proj = (p: number[]): [number, number] => {
    if (mode === "2d") return [p[0], p[1]];
    const rx = -Math.sin(yaw), ry = Math.cos(yaw);
    const x = p[0] * -rx + p[1] * -ry;
    const y = -Math.sin(pitch) * (p[0] * Math.cos(yaw) + p[1] * Math.sin(yaw)) + Math.cos(pitch) * p[2];
    return [-x, y];
  };
  const pts = segments.flatMap((s) => [proj(s.from), proj(s.to)]);
  if (!pts.length) return;
  const xs = pts.map((p) => p[0]), ys = pts.map((p) => p[1]);
  const minX = Math.min(...xs), maxX = Math.max(...xs), minY = Math.min(...ys), maxY = Math.max(...ys);
  const k = Math.min((w - 16) / Math.max(maxX - minX, 1), (h - 16) / Math.max(maxY - minY, 1));
  const ox = w / 2 - ((minX + maxX) / 2) * k, oy = h / 2 + ((minY + maxY) / 2) * k;
  ctx.lineCap = "round";
  for (const s of segments) {
    const a = proj(s.from), b = proj(s.to);
    ctx.strokeStyle = s.color;
    ctx.lineWidth = Math.max(1, s.width * 0.6);
    ctx.beginPath(); ctx.moveTo(ox + a[0] * k, oy - a[1] * k); ctx.lineTo(ox + b[0] * k, oy - b[1] * k); ctx.stroke();
  }
}
