import { run, type Mode, type RunResult } from "./lang";
import { createController, type ControllerState } from "./controller";
import { createWorkspace, shareHash, parseShareHash, toLogoFile, fromLogoFile } from "./workspace";
import { EXAMPLES } from "./examples";
import { CHALLENGES, checkChallenge, type Challenge } from "./challenges";
import { Editor } from "./ui/editor";
import { Viewport } from "./ui/viewport";
import { drawThumb } from "./ui/thumb";
import { DOC_COMMANDS, DOC_SECTIONS } from "./ui/docs";

declare const __VERSION__: string;
const VERSION = typeof __VERSION__ === "string" ? __VERSION__ : "dev";

const $ = <T extends HTMLElement = HTMLElement>(sel: string) => document.querySelector(sel) as T;
const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

let storage: Storage | null = null;
try { storage = window.localStorage; } catch { /* storage blocked */ }
const ws = createWorkspace({ storage, confirm: (m) => window.confirm(m) });
const controller = createController({ onChange: (s) => onState(s) });
const editor = new Editor($("#editor"));
let viewport: Viewport | null = null;
try { viewport = new Viewport($<HTMLCanvasElement>("#view")); }
catch (e) { $("#view-error").hidden = false; $("#view-error").textContent = `Podgląd rysunku jest niedostępny: ${(e as Error).message}`; }

let activeChallenge: Challenge | null = null;
/** Source the controller currently holds; used to detect edits. */
let loadedSource: string | null = null;

// ---------- status ----------
function status(text: string, kind: "info" | "ok" | "error" = "info") {
  const el = $("#status-msg");
  el.textContent = text;
  el.dataset.kind = kind;
}

let toastTimer = 0;
function toast(text: string) {
  const t = $("#toast");
  t.textContent = text;
  t.hidden = false;
  clearTimeout(toastTimer);
  toastTimer = window.setTimeout(() => (t.hidden = true), 3200);
}

const runBtn = $<HTMLButtonElement>("#btn-run"), stepBtn = $<HTMLButtonElement>("#btn-step");
const pauseBtn = $<HTMLButtonElement>("#btn-pause"), resetBtn = $<HTMLButtonElement>("#btn-reset");

function onState(s: ControllerState) {
  viewport?.setScene(s.segments, s.turtle);
  editor.setCurrent(s.status === "running" || s.status === "paused" ? s.current?.line ?? null : null);
  editor.setError(s.error ? { ...s.error } : null);
  pauseBtn.disabled = !(s.status === "running" || s.status === "paused");
  const paused = s.status === "paused";
  pauseBtn.querySelector(".label")!.textContent = paused ? "Wznów" : "Pauza";
  pauseBtn.setAttribute("aria-label", paused ? "Wznów (Ctrl+.)" : "Pauza (Ctrl+.)");
  document.body.dataset.run = s.status;
  const n = s.segments.length;
  const odc = n === 1 ? "odcinek" : n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 10 || n % 100 >= 20) ? "odcinki" : "odcinków";
  if (s.status === "error" && s.error) status(`Błąd w wierszu ${s.error.line}, kolumna ${s.error.column}: ${s.error.message}`, "error");
  else if (s.status === "done") {
    status(`Gotowe: ${n} ${odc}.`, "ok");
    if (viewport && !viewport.fits()) viewport.fit();
  } else if (s.status === "running") status(`Rysuję… ${n} ${odc}`);
  else if (paused) status(s.current ? `Wstrzymano w wierszu ${s.current.line}. ${n} ${odc}.` : "Wstrzymano.");
  else status("Gotowy do rysowania.");
}

// ---------- execution ----------
const mode = () => ws.mode();

function fresh() {
  loadedSource = editor.value;
  controller.load(editor.value, mode());
}

function doRun() {
  const st = controller.state().status;
  if (st === "paused" && loadedSource === editor.value) return controller.resume();
  fresh();
  controller.run();
}
function doStep() {
  const st = controller.state().status;
  if (!(st === "paused" || st === "running") || loadedSource !== editor.value) fresh();
  controller.step();
}
function doPause() {
  const st = controller.state().status;
  if (st === "running") controller.pause();
  else if (st === "paused") controller.resume();
}
function doReset() { controller.reset(); loadedSource = null; }

runBtn.addEventListener("click", doRun);
stepBtn.addEventListener("click", doStep);
pauseBtn.addEventListener("click", doPause);
resetBtn.addEventListener("click", doReset);

const speed = $<HTMLInputElement>("#speed");
const speedOut = $("#speed-out");
function setSpeed(v: number) {
  controller.setSpeed(v);
  speed.value = String(v);
  const label = v >= 10 ? "natychmiast" : `${v} z 10`;
  speedOut.textContent = label;
  speed.setAttribute("aria-valuetext", label);
  ws.setPref("speed", String(v));
}
speed.addEventListener("input", () => setSpeed(+speed.value));
setSpeed(+(ws.getPref("speed") ?? 6));

editor.onInput = (text) => {
  if (activeChallenge) ws.setPref(`ch:${activeChallenge.id}`, text);
  else ws.edit(text);
