import { drawThumb } from "./ui/thumb";
import { DOC_COMMANDS, DOC_SECTIONS } from "./ui/docs";

declare const __VERSION__: string;
const VERSION = typeof __VERSION__ === "string" ? __VERSION__ : "dev";

const $ = <T extends HTMLElement = HTMLElement>(sel: string) => document.querySelector(sel) as T;
const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

let storage: Storage | null = null;
try { storage = window.localStorage; } catch { /* storage blocked */ }
const ws = createWorkspace({ storage, confirm: (m) => window.confirm(m) });
const controller = createController({ onChange: (s) => onState(s) });
const editor = new Editor($("#editor"));
let viewport: Viewport | null = null;
try { viewport = new Viewport($<HTMLCanvasElement>("#view")); }
catch (e) { $("#view-error").hidden = false; $("#view-error").textContent = `Podgląd rysunku jest niedostępny: ${(e as Error).message}`; }

let activeChallenge: Challenge | null = null;
/** Source the controller currently holds; used to detect edits. */
let loadedSource: string | null = null;

// ---------- status ----------
function status(text: string, kind: "info" | "ok" | "error" = "info") {
  const el = $("#status-msg");
  el.textContent = text;
  el.dataset.kind = kind;
}

let toastTimer = 0;
function toast(text: string) {
  const t = $("#toast");
  t.textContent = text;
  t.hidden = false;
  clearTimeout(toastTimer);
  toastTimer = window.setTimeout(() => (t.hidden = true), 3200);
}

const runBtn = $<HTMLButtonElement>("#btn-run"), stepBtn = $<HTMLButtonElement>("#btn-step");
const pauseBtn = $<HTMLButtonElement>("#btn-pause"), resetBtn = $<HTMLButtonElement>("#btn-reset");

function onState(s: ControllerState) {
  viewport?.setScene(s.segments, s.turtle);
  editor.setCurrent(s.status === "running" || s.status === "paused" ? s.current?.line ?? null : null);
  editor.setError(s.error ? { ...s.error } : null);
  pauseBtn.disabled = !(s.status === "running" || s.status === "paused");
  const paused = s.status === "paused";
  pauseBtn.querySelector(".label")!.textContent = paused ? "Wznów" : "Pauza";
  pauseBtn.setAttribute("aria-label", paused ? "Wznów (Ctrl+.)" : "Pauza (Ctrl+.)");
  document.body.dataset.run = s.status;
  const n = s.segments.length;
  const odc = n === 1 ? "odcinek" : n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 10 || n % 100 >= 20) ? "odcinki" : "odcinków";
  if (s.status === "error" && s.error) status(`Błąd w wierszu ${s.error.line}, kolumna ${s.error.column}: ${s.error.message}`, "error");
  else if (s.status === "done") {
    status(`Gotowe: ${n} ${odc}.`, "ok");
    if (viewport && !viewport.fits()) viewport.fit();
  } else if (s.status === "running") status(`Rysuję… ${n} ${odc}`);
  else if (paused) status(s.current ? `Wstrzymano w wierszu ${s.current.line}. ${n} ${odc}.` : "Wstrzymano.");
  else status("Gotowy do rysowania.");
}

// ---------- execution ----------
const mode = () => ws.mode();

function fresh() {
  loadedSource = editor.value;
  controller.load(editor.value, mode());
}

function doRun() {
  const st = controller.state().status;
  if (st === "paused" && loadedSource === editor.value) return controller.resume();
  fresh();
  controller.run();
}
function doStep() {
  const st = controller.state().status;
  if (!(st === "paused" || st === "running") || loadedSource !== editor.value) fresh();
  controller.step();
}
function doPause() {
  const st = controller.state().status;
  if (st === "running") controller.pause();
  else if (st === "paused") controller.resume();
}
function doReset() { controller.reset(); loadedSource = null; }

runBtn.addEventListener("click", doRun);
stepBtn.addEventListener("click", doStep);
pauseBtn.addEventListener("click", doPause);
resetBtn.addEventListener("click", doReset);

const speed = $<HTMLInputElement>("#speed");
const speedOut = $("#speed-out");
function setSpeed(v: number) {
  controller.setSpeed(v);
  speed.value = String(v);
  const label = v >= 10 ? "natychmiast" : `${v} z 10`;
  speedOut.textContent = label;
  speed.setAttribute("aria-valuetext", label);
  ws.setPref("speed", String(v));
}
speed.addEventListener("input", () => setSpeed(+speed.value));
setSpeed(+(ws.getPref("speed") ?? 6));

editor.onInput = (text) => {
  if (activeChallenge) ws.setPref(`ch:${activeChallenge.id}`, text);
  else ws.edit(text);
  const st = controller.state().status;
  if (st === "running" || st === "paused") {
    controller.reset();
    loadedSource = null;
    status("Program został zmieniony, więc wykonanie przerwano. Uruchom go ponownie.");
  } else if (st === "error" || st === "done") {
    // Keep the drawing; only the stale error marker goes away.
    editor.setError(null);
  }
};

// ---------- modes ----------
function applyMode(m: Mode) {
  document.querySelectorAll<HTMLButtonElement>("[data-mode]").forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.mode === m)));
  document.body.dataset.mode = m;
  viewport?.setMode(m);
  $("#view").setAttribute("aria-label", m === "3d"
    ? "Rysunek 3D. Przeciągnij, aby obracać; z Shift przesuwać; kółko lub szczypanie przybliża. Klawisze: strzałki, plus, minus, 0 dopasowuje."
    : "Rysunek 2D. Przeciągnij, aby przesuwać; kółko lub szczypanie przybliża. Klawisze: strzałki, plus, minus, 0 dopasowuje.");
}

function setMode(m: Mode) {
  if (activeChallenge && activeChallenge.mode !== m) leaveChallenge();
  ws.setMode(m);
  editor.value = ws.source();
  doReset();
  applyMode(m);
  viewport?.resetView();
}
document.querySelectorAll<HTMLButtonElement>("[data-mode]").forEach((b) => b.addEventListener("click", () => setMode(b.dataset.mode as Mode)));

/** Put a program in the editor and draw it at once. */
function showProgram(src: string, m: Mode, animate = false) {
  editor.value = src;
  applyMode(m);
  fresh();
  if (animate) controller.run(); else controller.runToEnd();
  viewport?.fit();
}

function loadInto(src: string, m: Mode, question: string, animate = true): boolean {
  if (activeChallenge) leaveChallenge();
  const prevMode = ws.mode();
  if (!ws.replace(src, m, question)) { ws.setMode(prevMode); return false; }
  updateRestore();
  go("#/");
  showProgram(src, m, animate);
  return true;
}

// ---------- files & sharing ----------
$("#btn-share").addEventListener("click", async () => {
  const url = location.href.replace(/#.*$/, "") + shareHash(editor.value, mode());
  if (url.length > 60000) toast("Uwaga: link jest bardzo długi i nie każda przeglądarka go obsłuży.");
  try {
    await navigator.clipboard.writeText(url);
    toast("Skopiowano link do schowka.");
  } catch {
    window.prompt("Skopiuj ten link:", url);
  }
});

function download(name: string, blob: Blob) {
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = name;
  document.body.append(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(a.href), 2000);
}

$("#btn-png").addEventListener("click", async () => {
  const blob = await viewport?.toBlob();
  if (blob) download(`logomocja-${mode()}.png`, blob);
  else toast("Nie udało się zapisać obrazu.");
});

$("#btn-save").addEventListener("click", () => {
  download(`program-${mode()}.logo`, new Blob([toLogoFile(editor.value, mode())], { type: "text/plain;charset=utf-8" }));
});

const fileInput = $<HTMLInputElement>("#file-input");
$("#btn-open").addEventListener("click", () => fileInput.click());
fileInput.addEventListener("change", async () => {
  const f = fileInput.files?.[0];
  fileInput.value = "";
  if (!f) return;
  if (f.size > 200_000) return toast("Ten plik jest za duży jak na program Logo.");
  const { source, mode: m } = fromLogoFile(await f.text());
  const target = m ?? (/\b(gora|góra|dol|dół|pp|pl|pitchup|pitchdown|rollright|rollleft|przechylprawo|przechyllewo)\b/i.test(source) ? "3d" : mode());
  if (loadInto(source, target, `Otworzyć plik „${f.name}”?`, false)) toast(`Otwarto plik ${f.name}.`);
});

const restoreBtn = $<HTMLButtonElement>("#btn-restore");
function updateRestore() { restoreBtn.hidden = ws.backup() === null; }
restoreBtn.addEventListener("click", () => {
  if (activeChallenge) leaveChallenge();
  if (!ws.restoreBackup()) return;
  editor.value = ws.source();
  applyMode(ws.mode());
  doReset();
  toast("Przywrócono poprzedni program. Zastąpiony program można przywrócić tym samym przyciskiem.");
});

// ---------- view controls ----------
$("#btn-fit").addEventListener("click", () => viewport?.fit());
$("#btn-view-reset").addEventListener("click", () => viewport?.resetView());
$("#btn-zoom-in").addEventListener("click", () => viewport?.zoom(1.25));
$("#btn-zoom-out").addEventListener("click", () => viewport?.zoom(0.8));

// ---------- theme ----------
const THEMES = ["system", "light", "dark"] as const;
const THEME_LABEL = { system: "systemowy", light: "jasny", dark: "ciemny" };
let theme = (ws.getPref("theme") as (typeof THEMES)[number]) ?? "system";
function applyTheme() {
  if (theme === "system") delete document.documentElement.dataset.theme;
  else document.documentElement.dataset.theme = theme;
  const btn = $("#btn-theme");
  btn.setAttribute("aria-label", `Motyw: ${THEME_LABEL[theme]}. Zmień motyw`);
  btn.title = `Motyw: ${THEME_LABEL[theme]}`;
  btn.dataset.theme = theme;
  viewport?.render();
  renderThumbs();
}
$("#btn-theme").addEventListener("click", () => {
  theme = THEMES[(THEMES.indexOf(theme) + 1) % THEMES.length];
  ws.setPref("theme", theme);
  applyTheme();
});
matchMedia("(prefers-color-scheme: dark)").addEventListener("change", () => viewport?.render());

// ---------- examples ----------
function renderExamples() {
  $("#examples-list").innerHTML = EXAMPLES.map((e) => `
    <li class="card">
      <canvas class="thumb" data-thumb="ex:${e.id}" aria-hidden="true"></canvas>
      <div class="card-body">
        <h3>${esc(e.title)} <span class="badge">${e.mode.toUpperCase()}</span></h3>
        <p>${esc(e.blurb)}</p>
        <button type="button" class="btn" data-example="${e.id}">Wczytaj <span class="sr-only">przykład ${esc(e.title)}</span></button>
      </div>
    </li>`).join("");
  document.querySelectorAll<HTMLButtonElement>("[data-example]").forEach((b) => b.addEventListener("click", () => {
    const ex = EXAMPLES.find((e) => e.id === b.dataset.example)!;
    if (loadInto(ex.source, ex.mode, `Wczytać przykład „${ex.title}”?`)) toast(`Wczytano przykład ${ex.title}.`);
  }));
}

const thumbData = new Map<string, { segs: RunResult["segments"]; mode: Mode }>();
function renderThumbs() {
  document.querySelectorAll<HTMLCanvasElement>("canvas[data-thumb]").forEach((c) => {
    if (c.offsetParent === null) return;
    const key = c.dataset.thumb!;
    let d = thumbData.get(key);
    if (!d) {
      const [kind, id] = key.split(":");
      const item = kind === "ex" ? EXAMPLES.find((e) => e.id === id)! : CHALLENGES.find((e) => e.id === id)!;
      const src = "source" in item ? item.source : item.solution;
      d = { segs: run(src, item.mode).segments, mode: item.mode };
      thumbData.set(key, d);
    }
    drawThumb(c, d.segs, d.mode);
  });
}

// ---------- challenges ----------
function renderChallenges() {
  const solved = new Set(ws.solved());
  $("#challenge-progress").textContent = `Rozwiązano ${solved.size} z ${CHALLENGES.length}.`;
  $("#challenge-meter").setAttribute("value", String(solved.size));
  $("#challenge-meter").setAttribute("max", String(CHALLENGES.length));
  $("#challenges-list").innerHTML = CHALLENGES.map((c, i) => `
    <li class="card ${solved.has(c.id) ? "solved" : ""}">
      <canvas class="thumb" data-thumb="ch:${c.id}" aria-hidden="true"></canvas>
      <div class="card-body">
        <h3>${i + 1}. ${esc(c.title)} <span class="badge">${c.mode.toUpperCase()}</span>
          ${solved.has(c.id) ? '<span class="badge ok">✓ rozwiązane</span>' : ""}</h3>
        <p>${esc(c.task)}</p>
        <button type="button" class="btn" data-challenge="${c.id}">${solved.has(c.id) ? "Rozwiąż ponownie" : "Rozwiąż"} <span class="sr-only">zadanie ${esc(c.title)}</span></button>
      </div>
    </li>`).join("");
  document.querySelectorAll<HTMLButtonElement>("[data-challenge]").forEach((b) => b.addEventListener("click", () => go(`#/wyzwania/${b.dataset.challenge}`)));
}

function enterChallenge(c: Challenge) {
  activeChallenge = c;
  ws.setMode(c.mode);
  const banner = $("#challenge");
  banner.hidden = false;
  $("#ch-title").textContent = c.title;
  $("#ch-task").textContent = c.task;
  $("#ch-hint").textContent = c.hint;
  $("#ch-result").textContent = "";
  $("#ch-result").removeAttribute("data-kind");
  editor.value = ws.getPref(`ch:${c.id}`) ?? `; ${c.task}\n`;
  applyMode(c.mode);
  doReset();
  viewport?.setGhost(run(c.solution, c.mode).segments);
  viewport?.fit();
  document.body.dataset.challenge = c.id;
}

function leaveChallenge() {
  activeChallenge = null;
  $("#challenge").hidden = true;
  viewport?.setGhost([]);
  delete document.body.dataset.challenge;
  editor.value = ws.source();
  doReset();
}

$("#ch-check").addEventListener("click", () => {
  if (!activeChallenge) return;
  const r = checkChallenge(activeChallenge, editor.value);
  fresh();
  controller.runToEnd();
  const out = $("#ch-result");
  out.textContent = (r.pass ? "Zaliczone! " : "Jeszcze nie. ") + r.reason;
  out.dataset.kind = r.pass ? "ok" : "error";
  if (r.pass) ws.markSolved(activeChallenge.id);
});
$("#ch-ghost").addEventListener("click", (e) => {
  const b = e.currentTarget as HTMLButtonElement;
  const on = b.getAttribute("aria-pressed") !== "true";
  b.setAttribute("aria-pressed", String(on));
  viewport?.setGhost(on && activeChallenge ? run(activeChallenge.solution, activeChallenge.mode).segments : []);
});
$("#ch-exit").addEventListener("click", () => { leaveChallenge(); go("#/wyzwania"); });

// ---------- reference ----------
function renderDocs() {
  const cmds = DOC_COMMANDS.map((c, i) => `
    <tr>
      <th scope="row"><code>${esc(c.names)}</code></th>
      <td><code>${esc(c.english)}</code></td>
      <td>${esc(c.arg)}</td>
      <td>${esc(c.desc)}<pre class="doc-code">${esc(c.example)}</pre>
        <button type="button" class="btn small" data-doc="c${i}">Wypróbuj <span class="sr-only">${esc(c.names.split(",")[0])}</span></button></td>
    </tr>`).join("");
  const sections = DOC_SECTIONS.map((s, i) => `
    <section class="doc-section" id="doc-${s.id}" aria-labelledby="doc-h-${s.id}">
      <h2 id="doc-h-${s.id}">${esc(s.title)}</h2>
      ${s.html}
      ${s.example ? `<pre class="doc-code">${esc(s.example.source)}</pre><button type="button" class="btn small" data-doc="s${i}">Wypróbuj <span class="sr-only">przykład: ${esc(s.title)}</span></button>` : ""}
    </section>`).join("");
  $("#docs-body").innerHTML = `
    <nav class="doc-toc" aria-label="Spis treści"><ul>
      <li><a href="#/pomoc" data-anchor="doc-polecenia">Polecenia</a></li>
      ${DOC_SECTIONS.map((s) => `<li><a href="#/pomoc" data-anchor="doc-${s.id}">${esc(s.title)}</a></li>`).join("")}
      <li><a href="#/pomoc" data-anchor="doc-skroty">Skróty klawiszowe</a></li>
    </ul></nav>
    <section class="doc-section" id="doc-polecenia" aria-labelledby="doc-h-pol">
      <h2 id="doc-h-pol">Polecenia</h2>
      <p>Każde polskie i angielskie słowo w tym samym wierszu działa identycznie.</p>
      <div class="table-wrap"><table>
        <thead><tr><th scope="col">Polecenie</th><th scope="col">Po angielsku</th><th scope="col">Argument</th><th scope="col">Działanie i przykład</th></tr></thead>
        <tbody>${cmds}</tbody>
      </table></div>
    </section>
    ${sections}
    <section class="doc-section" id="doc-skroty" aria-labelledby="doc-h-sk"><h2 id="doc-h-sk">Skróty klawiszowe</h2>${$("#shortcuts-list").outerHTML.replace('id="shortcuts-list"', "")}</section>`;
  document.querySelectorAll<HTMLButtonElement>("[data-doc]").forEach((b) => b.addEventListener("click", () => {
    const id = b.dataset.doc!;
    const ex = id[0] === "c" ? { source: DOC_COMMANDS[+id.slice(1)].example, mode: DOC_COMMANDS[+id.slice(1)].mode } : DOC_SECTIONS[+id.slice(1)].example!;
    loadInto(ex.source, ex.mode, "Wypróbować ten przykład?");
  }));
  document.querySelectorAll<HTMLAnchorElement>("[data-anchor]").forEach((a) => a.addEventListener("click", (e) => {
    e.preventDefault();
    const t = document.getElementById(a.dataset.anchor!)!;
    t.scrollIntoView({ behavior: matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth" });
    t.setAttribute("tabindex", "-1");
    t.focus({ preventScroll: true });
  }));
}

// ---------- routing ----------
const PAGES = ["studio", "przyklady", "wyzwania", "pomoc"];
function go(hash: string) {
  if (location.hash !== hash) location.hash = hash;
  else route();
}

function route() {
  const hash = location.hash || "#/";
  const shared = parseShareHash(hash);
  if (shared) {
    history.replaceState(null, "", location.href.replace(/#.*$/, "") + "#/");
    if (activeChallenge) leaveChallenge();
    if (ws.replace(shared.source, shared.mode, "Otworzyć udostępniony program?")) {
      updateRestore();
      show("studio");
      showProgram(shared.source, shared.mode);
      toast("Otwarto udostępniony program.");
    } else show("studio");
    return;
  }
  const m = /^#\/([a-z]*)(?:\/([\w-]+))?/.exec(hash);
  const page = m?.[1] || "studio";
  if (page === "wyzwania" && m?.[2]) {
    const c = CHALLENGES.find((x) => x.id === m[2]);
    if (c) { show("studio"); if (activeChallenge?.id !== c.id) enterChallenge(c); return; }
  }
  if (page !== "studio" && activeChallenge && page !== "pomoc") leaveChallenge();
  show(PAGES.includes(page) ? page : "studio");
}

function show(page: string) {
  for (const p of PAGES) $(`#page-${p}`).hidden = p !== page;
  document.querySelectorAll<HTMLAnchorElement>("[data-nav]").forEach((a) => {
    if (a.dataset.nav === page) a.setAttribute("aria-current", "page"); else a.removeAttribute("aria-current");
  });
  document.body.dataset.page = page;
  if (page === "wyzwania") renderChallenges();
  if (page === "studio") viewport?.request();
  requestAnimationFrame(renderThumbs);
  const titles: Record<string, string> = { studio: "Studio", przyklady: "Przykłady", wyzwania: "Wyzwania", pomoc: "Pomoc" };
  document.title = `${titles[page]} · Logomocja`;
}
addEventListener("hashchange", route);

// ---------- shortcuts ----------
addEventListener("keydown", (e) => {
  if (document.body.dataset.page !== "studio") return;
  const mod = e.ctrlKey || e.metaKey;
  if (mod && e.key === "Enter") { e.preventDefault(); if (e.shiftKey) doStep(); else doRun(); }
  else if (mod && e.key === ".") { e.preventDefault(); doPause(); }
  else if (e.key === "Escape" && !e.defaultPrevented) {
    const st = controller.state().status;
    if (st !== "idle") { e.preventDefault(); doReset(); }
  }
});

// ---------- start ----------
renderExamples();
renderDocs();
applyTheme();
editor.value = ws.source();
applyMode(ws.mode());
updateRestore();
onState(controller.state());
route();
addEventListener("resize", () => requestAnimationFrame(renderThumbs));

const nextFrame = () => new Promise<void>((r) => requestAnimationFrame(() => r()));

/** Testing hook. */
(window as unknown as { logomocja: unknown }).logomocja = {
  version: VERSION,
  run: (source: string, m: Mode): RunResult => run(String(source), m === "3d" ? "3d" : "2d"),
  async open(source: string, m: Mode): Promise<RunResult> {
    const md: Mode = m === "3d" ? "3d" : "2d";
    if (activeChallenge) leaveChallenge();
    show("studio");
    if (location.hash && location.hash !== "#/") history.replaceState(null, "", location.href.replace(/#.*$/, "") + "#/");
    ws.setMode(md);
    ws.edit(String(source));
    showProgram(String(source), md);
    viewport?.render();
    await nextFrame();
    viewport?.fit();
    await nextFrame();
    const s = controller.state();
    return { segments: s.segments, error: s.error };
  },
};
EOF

