}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg: #15171a; --panel: #1d2024; --panel-2: #262a2f; --ink: #ece7dc; --muted: #a9a294; --line: #363b42;
    --accent: #3cc49e; --accent-ink: #9ff0d6; --on-accent: #06241c; --warm: #e39a5f; --danger: #ff8a80; --danger-bg: #3a1f1d;
    --ok: #6fdcaa; --ok-bg: #173327;
    --canvas: #1a1c20; --grid: #262a30; --axis: #5b6370; --ghost: #c9bfa9;
    --turtle: #f2b84b; --turtle-edge: #fff2cf; --focus: #7cb7ff; --cur-line: rgba(242, 184, 75, .18);
    --tk-cmd: #5fd4b1; --tk-k: #d49bf0; --tk-n: #f0a46c; --tk-v: #8fb8ff; --tk-p: #e8c66e; --tk-c: #858b94; --tk-b: #b5ae9f; --tk-s: #f0a46c; --tk-o: #b5ae9f;
    color-scheme: dark;
  }
}
:root[data-theme="dark"] {
  --bg: #15171a; --panel: #1d2024; --panel-2: #262a2f; --ink: #ece7dc; --muted: #a9a294; --line: #363b42;
  --accent: #3cc49e; --accent-ink: #9ff0d6; --on-accent: #06241c; --warm: #e39a5f; --danger: #ff8a80; --danger-bg: #3a1f1d;
  --ok: #6fdcaa; --ok-bg: #173327;
  --canvas: #1a1c20; --grid: #262a30; --axis: #5b6370; --ghost: #c9bfa9;
  --turtle: #f2b84b; --turtle-edge: #fff2cf; --focus: #7cb7ff; --cur-line: rgba(242, 184, 75, .18);
  --tk-cmd: #5fd4b1; --tk-k: #d49bf0; --tk-n: #f0a46c; --tk-v: #8fb8ff; --tk-p: #e8c66e; --tk-c: #858b94; --tk-b: #b5ae9f; --tk-s: #f0a46c; --tk-o: #b5ae9f;
  color-scheme: dark;
}

* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; }
body {
  background: var(--bg); color: var(--ink);
  font: 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, "Noto Sans", sans-serif;
  display: flex; flex-direction: column; min-height: 100dvh;
}
:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; border-radius: 4px; }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.skip { position: absolute; left: 8px; top: -40px; background: var(--panel); padding: 6px 10px; z-index: 10; border-radius: 6px; }
.skip:focus { top: 8px; }
code, kbd, pre { font-family: var(--mono); }
code { background: var(--panel-2); padding: 1px 5px; border-radius: 4px; font-size: .92em; }
kbd { border: 1px solid var(--line); border-bottom-width: 2px; border-radius: 4px; padding: 0 5px; font-size: .85em; background: var(--panel); }

/* header */
.top { display: flex; align-items: center; gap: 16px; padding: 8px 16px; border-bottom: 1px solid var(--line); background: var(--panel); flex-wrap: wrap; }
.brand { display: flex; align-items: center; gap: 8px; color: var(--ink); text-decoration: none; font-weight: 750; font-size: 19px; letter-spacing: -.01em; }
.nav { display: flex; gap: 2px; flex-wrap: wrap; }
.nav a { color: var(--muted); text-decoration: none; padding: 6px 10px; border-radius: 8px; font-weight: 550; }
.nav a:hover { background: var(--panel-2); color: var(--ink); }
.nav a[aria-current="page"] { color: var(--accent-ink); background: color-mix(in srgb, var(--accent) 16%, transparent); }
.top-right { margin-left: auto; display: flex; gap: 8px; align-items: center; }
.seg { display: inline-flex; border: 1px solid var(--line); border-radius: 9px; overflow: hidden; }
.seg button { border: 0; background: transparent; color: var(--muted); padding: 6px 14px; font: inherit; font-weight: 650; cursor: pointer; min-height: 36px; }
.seg button[aria-pressed="true"] { background: var(--accent); color: var(--on-accent); }

/* buttons */
.btn, .icon-btn {
  font: inherit; font-weight: 600; color: var(--ink); background: var(--panel); border: 1px solid var(--line);
  border-radius: 8px; padding: 6px 12px; min-height: 36px; cursor: pointer; display: inline-flex; align-items: center; gap: 6px;
}
.btn:hover, .icon-btn:hover { background: var(--panel-2); }
.btn:disabled { opacity: .45; cursor: not-allowed; }
.btn.primary { background: var(--accent); color: var(--on-accent); border-color: var(--accent); }
.btn.primary:hover { filter: brightness(1.07); }
.btn.small { padding: 4px 10px; min-height: 32px; font-size: 14px; }
.btn[aria-pressed="true"] { background: color-mix(in srgb, var(--accent) 18%, var(--panel)); border-color: var(--accent); }
.icon-btn { justify-content: center; min-width: 36px; padding: 4px; font-size: 18px; line-height: 1; }

/* studio */
main { flex: 1; display: flex; flex-direction: column; min-height: 0; }
.studio { flex: 1; display: grid; grid-template-columns: minmax(340px, 5fr) 7fr; gap: 12px; padding: 12px; min-height: 0; }
.studio[hidden] { display: none; }
.pane { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); min-height: 0; }
.code-pane { display: flex; flex-direction: column; padding: 10px; gap: 8px; min-height: 0; }
.toolbar { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
.speed { display: inline-flex; align-items: center; gap: 6px; margin-left: auto; color: var(--muted); font-size: 14px; }
.speed input { width: 110px; accent-color: var(--accent); }
.speed output { min-width: 6.5em; font-variant-numeric: tabular-nums; }
.status { margin: 0; min-height: 1.5em; font-size: 14px; color: var(--muted); }
.status[data-kind="error"] { color: var(--danger); font-weight: 600; }
.status[data-kind="ok"] { color: var(--ok); }
.filebar { display: flex; flex-wrap: wrap; gap: 6px; }
.shortcuts { font-size: 14px; color: var(--muted); }
.shortcuts summary { cursor: pointer; padding: 2px 0; }
dl#shortcuts-list, .doc-section dl { display: grid; gap: 4px; margin: 6px 0 0; }
dl div { display: flex; gap: 10px; flex-wrap: wrap; }
dt { min-width: 15em; } dd { margin: 0; }

/* editor */
.editor { --lh: 21px; flex: 1; min-height: 220px; display: flex; border: 1px solid var(--line); border-radius: 8px; background: var(--canvas); overflow: hidden; font: 14px/var(--lh) var(--mono); position: relative; }
.editor:focus-within { outline: 3px solid var(--focus); outline-offset: 1px; }
.ed-gutter { width: 3.4em; flex: none; overflow: hidden; text-align: right; padding: 8px 8px 50vh 0; color: var(--muted); background: var(--panel-2); user-select: none; font-variant-numeric: tabular-nums; }
.ed-gutter .g { display: block; height: var(--lh); }
.ed-gutter .g.bad { color: var(--on-accent); background: var(--danger); border-radius: 0 4px 4px 0; }
.ed-gutter .g.cur { color: var(--ink); font-weight: 700; background: var(--cur-line); }
.ed-body { position: relative; flex: 1; min-width: 0; overflow: hidden; }
.ed-pre, .ed-text { margin: 0; padding: 8px 12px; font: inherit; white-space: pre; tab-size: 2; letter-spacing: 0; word-spacing: 0; }
.ed-pre { position: absolute; inset: 0 auto auto 0; min-width: 100%; pointer-events: none; color: var(--ink); }
.ed-pre .ln { display: inline-block; min-width: 100%; }
.ed-pre .ln.cur { background: var(--cur-line); box-shadow: inset 3px 0 0 var(--turtle); }
.ed-pre .ln.bad { background: color-mix(in srgb, var(--danger) 9%, transparent); }
.ed-text { position: absolute; inset: 0; width: 100%; height: 100%; resize: none; border: 0; outline: 0; background: transparent; color: transparent; caret-color: var(--ink); overflow: auto; }
.ed-text::selection { background: color-mix(in srgb, var(--focus) 30%, transparent); color: transparent; }
.ed-err { text-decoration: wavy underline var(--danger) 1.5px; text-underline-offset: 3px; background: color-mix(in srgb, var(--danger) 16%, transparent); border-radius: 2px; }
.ed-bubble { position: absolute; top: var(--top); left: var(--left); max-width: min(34em, calc(100% - 24px)); background: var(--danger); color: #fff; font: 600 12.5px/1.35 system-ui, sans-serif; padding: 5px 9px; border-radius: 6px; pointer-events: none; z-index: 2; box-shadow: 0 4px 14px rgba(0,0,0,.18); }
.ed-bubble::before { content: ""; position: absolute; top: -5px; left: 8px; border: 5px solid transparent; border-top: 0; border-bottom-color: var(--danger); }
.tk-cmd { color: var(--tk-cmd); font-weight: 650; } .tk-k { color: var(--tk-k); font-weight: 650; } .tk-n { color: var(--tk-n); }
.tk-v { color: var(--tk-v); } .tk-p { color: var(--tk-p); font-weight: 650; } .tk-c { color: var(--tk-c); font-style: italic; }
.tk-b { color: var(--tk-b); font-weight: 700; } .tk-pa, .tk-o { color: var(--tk-o); } .tk-s { color: var(--tk-s); } .tk-bad { text-decoration: underline dotted var(--danger); }
.swatch { display: inline-block; width: .7em; height: .7em; border-radius: 2px; background: var(--sw); margin-right: 0; vertical-align: -1px; box-shadow: 0 0 0 1px var(--line); position: absolute; transform: translate(-0.9em, 0); }

/* challenge banner */
.challenge { border: 1px solid color-mix(in srgb, var(--warm) 50%, var(--line)); background: color-mix(in srgb, var(--warm) 9%, var(--panel)); border-radius: 8px; padding: 10px 12px; display: grid; gap: 6px; }
.challenge[hidden] { display: none; }
.challenge h2 { margin: 0; font-size: 17px; }
.challenge p { margin: 0; }
.challenge .hint { color: var(--muted); font-size: 14px; }
.ch-actions { display: flex; gap: 6px; flex-wrap: wrap; }
#ch-result:empty { display: none; }
#ch-result { padding: 6px 10px; border-radius: 6px; font-weight: 600; }
#ch-result[data-kind="ok"] { background: var(--ok-bg); color: var(--ok); }
#ch-result[data-kind="error"] { background: var(--danger-bg); color: var(--danger); }

/* view */
.view-pane { position: relative; overflow: hidden; min-height: 300px; }
#view { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; cursor: grab; border-radius: var(--radius); }
#view:active { cursor: grabbing; }
#view:focus-visible { outline-offset: -3px; }
.viewbar { position: absolute; right: 10px; top: 10px; display: flex; gap: 6px; flex-wrap: wrap; justify-content: end; }
.viewbar .btn, .viewbar .icon-btn { background: color-mix(in srgb, var(--panel) 88%, transparent); backdrop-filter: blur(4px); }
.view-hint { position: absolute; left: 12px; bottom: 8px; margin: 0; font-size: 12.5px; color: var(--muted); pointer-events: none; }
body[data-mode="2d"] .only-3d, body[data-mode="3d"] .only-2d { display: none; }
.view-error { position: absolute; inset: auto 12px 40px 12px; margin: 0; padding: 8px 12px; background: var(--danger-bg); color: var(--danger); border-radius: 8px; }

/* pages */
.page { padding: 20px clamp(14px, 4vw, 40px) 48px; max-width: 1180px; width: 100%; margin: 0 auto; }
.page h1 { margin: 0 0 6px; font-size: 28px; letter-spacing: -.015em; }
.lead { color: var(--muted); margin-top: 0; max-width: 60em; }
.cards { list-style: none; padding: 0; margin: 16px 0 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: 12px; }
.card { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; display: flex; flex-direction: column; }
.card.solved { border-color: color-mix(in srgb, var(--ok) 55%, var(--line)); }
.thumb { width: 100%; height: 150px; display: block; background: var(--canvas); border-bottom: 1px solid var(--line); }
.card-body { padding: 10px 12px 12px; display: flex; flex-direction: column; gap: 6px; flex: 1; }
.card-body h3 { margin: 0; font-size: 16px; display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
.card-body p { margin: 0; color: var(--muted); flex: 1; }
.card-body .btn { align-self: flex-start; }
.badge { font-size: 11px; font-weight: 700; padding: 1px 6px; border-radius: 99px; background: var(--panel-2); color: var(--muted); letter-spacing: .03em; }
.badge.ok { background: var(--ok-bg); color: var(--ok); }
meter { width: 160px; vertical-align: middle; }

